:root {
  --ash: #cfc4b4;
  --blood: #8d1b18;
  --gold: #d9ab5c;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: #050508;
  overflow: hidden;
  color: var(--ash);
  font-family: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
  overscroll-behavior: none;
}

#stage {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse at 50% 42%, #191419 0%, #08070a 58%, #030304 100%);
}

#frame {
  position: relative;
  width: 480px;
  height: 270px;
  box-shadow:
    0 0 0 1px #2a2020,
    0 0 60px rgba(140, 40, 24, 0.14),
    0 30px 80px rgba(0, 0, 0, 0.8);
  background: #000;
  overflow: hidden;
  isolation: isolate;
}

#game {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: #000;
  touch-action: none;
}

/* subtle CRT scanlines + vignette; toggled from Options */
#crt {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 180ms linear;
  background:
    repeating-linear-gradient(
      to bottom,
      rgba(0, 0, 0, 0.16) 0px,
      rgba(0, 0, 0, 0.16) 1px,
      rgba(255, 255, 255, 0.012) 2px,
      rgba(255, 255, 255, 0.012) 3px
    ),
    radial-gradient(ellipse at 50% 50%, rgba(0, 0, 0, 0) 52%, rgba(0, 0, 0, 0.42) 100%);
  mix-blend-mode: multiply;
}
body.crt-on #crt { opacity: 1; }

body.shake #frame { animation: none; }

/* touch controls */
#touch {
  display: none;
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 10px max(14px, env(safe-area-inset-left)) calc(12px + env(safe-area-inset-bottom)) max(14px, env(safe-area-inset-right));
  justify-content: space-between;
  align-items: flex-end;
  pointer-events: none;
  z-index: 20;
}
body.touch-play #touch { display: flex; }

#touch .pad,
#touch .actions {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  pointer-events: none;
}

.tbtn {
  pointer-events: auto;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  border: 2px solid rgba(200, 160, 110, 0.35);
  background: radial-gradient(circle at 50% 35%, rgba(70, 40, 32, 0.68), rgba(14, 10, 12, 0.62));
  color: #e8d8bd;
  font: 700 13px/1 ui-monospace, monospace;
  letter-spacing: 0.5px;
  border-radius: 50%;
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  backdrop-filter: blur(2px);
  box-shadow: inset 0 0 12px rgba(0, 0, 0, 0.7), 0 2px 10px rgba(0, 0, 0, 0.5);
}
.tbtn:active { transform: translateY(1px); background: radial-gradient(circle at 50% 35%, rgba(150, 70, 42, 0.8), rgba(40, 16, 14, 0.8)); }
.tbtn.big { width: 74px; height: 74px; font-size: 15px; border-color: rgba(210, 120, 80, 0.55); }
.tbtn.small { width: 48px; height: 48px; font-size: 10px; }
.tbtn.dpad { border-radius: 14px; width: 60px; height: 54px; font-size: 16px; }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 600px) and (orientation: landscape) {
  #frame { box-shadow: none; }
}

// Persistent progress + settings stored in localStorage.
const KEY = 'ashes-of-olympus-v1';

const DEFAULTS = {
  settings: {
    volume: 0.65,
    shake: true,
    blood: true,
    crt: true,
  },
  progress: {
    bestScore: 0,
    maxWave: 0,
    kills: 0,
    deaths: 0,
    runs: 0,
    cleared: false,
    run: null, // { wave, score, hp, rage } checkpoint
    unlocked: [],
  },
};

function clone(obj) {
  return JSON.parse(JSON.stringify(obj));
}

export const Save = {
  data: clone(DEFAULTS),

  load() {
    try {
      const raw = localStorage.getItem(KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        this.data = {
          settings: { ...DEFAULTS.settings, ...(parsed.settings || {}) },
          progress: { ...DEFAULTS.progress, ...(parsed.progress || {}) },
        };
      }
    } catch {
      this.data = clone(DEFAULTS);
    }
    return this.data;
  },

  persist() {
    try {
      localStorage.setItem(KEY, JSON.stringify(this.data));
    } catch {
      /* private mode / storage blocked: game still works for the session */
    }
  },

  get settings() { return this.data.settings; },
  get progress() { return this.data.progress; },

  setSetting(key, value) {
    this.data.settings[key] = value;
    this.persist();
  },

  checkpoint(run) {
    this.data.progress.run = run ? { ...run } : null;
    this.persist();
  },

  clearCheckpoint() {
    this.data.progress.run = null;
    this.persist();
  },

  recordRun({ score, wave, kills, cleared = false, died = false }) {
    const p = this.data.progress;
    p.bestScore = Math.max(p.bestScore, Math.floor(score));
    p.maxWave = Math.max(p.maxWave, wave);
    p.kills += kills;
    if (died) p.deaths += 1;
    if (cleared) p.cleared = true;
    if (cleared || died) p.run = null;
    this.persist();
  },

  unlock(...ids) {
    const p = this.data.progress;
    let added = false;
    for (const id of ids) {
      if (!p.unlocked.includes(id)) {
        p.unlocked.push(id);
        added = true;
      }
    }
    if (added) this.persist();
    return added;
  },

  reset() {
    this.data = clone(DEFAULTS);
    this.persist();
  },
};

export const TREASURES = [
  {
    id: 'blades',
    name: 'BLADES OF CHAOS',
    desc: 'Duas laminas forjadas no inferno. Sempre com voce.',
    always: true,
  },
  {
