// --------------------------------------------------------------- utilities
function lerpColor(a, b, t) {
  const pa = parseInt(a.slice(1), 16);
  const pb = parseInt(b.slice(1), 16);
  const r = Math.round((((pa >> 16) & 255) * (1 - t) + ((pb >> 16) & 255) * t));
  const g = Math.round((((pa >> 8) & 255) * (1 - t) + ((pb >> 8) & 255) * t));
  const bl = Math.round(((pa & 255) * (1 - t) + (pb & 255) * t));
  return `rgb(${r},${g},${bl})`;
}

function cloudBlob(ctx, rnd, cx, cy, rx, ry, color, alpha) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = color;
  for (let i = 0; i < 9; i++) {
    const ox = (rnd() - 0.5) * rx * 1.4;
    const oy = (rnd() - 0.5) * ry * 1.6;
    const r = rx * (0.28 + rnd() * 0.4);
    ctx.beginPath();
    ctx.ellipse(cx + ox, cy + oy, r, r * (0.35 + rnd() * 0.3), 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

// ------------------------------------------------------------ storm backdrop
function buildSky() {
  const c = makeCanvas(240, 135);
  const ctx = c.getContext('2d');
  const rnd = mulberry32(1337);

  const grad = ctx.createLinearGradient(0, 0, 0, 135);
  grad.addColorStop(0, '#070a10');
  grad.addColorStop(0.32, '#18202a');
  grad.addColorStop(0.55, '#3b424b');
  grad.addColorStop(0.72, '#786b5c');
  grad.addColorStop(0.84, '#b09272');
  grad.addColorStop(1, '#3a2a20');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 240, 135);

  // break of sun behind Kratos
  const sun = ctx.createRadialGradient(218, 66, 2, 218, 66, 62);
  sun.addColorStop(0, 'rgba(255,247,214,0.95)');
  sun.addColorStop(0.16, 'rgba(255,231,178,0.8)');
  sun.addColorStop(0.42, 'rgba(236,186,124,0.32)');
  sun.addColorStop(1, 'rgba(180,120,70,0)');
  ctx.fillStyle = sun;
  ctx.fillRect(0, 0, 240, 135);

  // heavy storm clouds
  for (let i = 0; i < 70; i++) {
    const y = rnd() * 92;
    const x = rnd() * 250 - 5;
    const dark = rnd() < 0.72;
    cloudBlob(ctx, rnd, x, y, 22 + rnd() * 38, 8 + rnd() * 16, dark ? '#141b24' : '#4b535d', 0.24 + rnd() * 0.3);
  }
  // lit cloud edges near the sun
  for (let i = 0; i < 20; i++) {
    cloudBlob(ctx, rnd, 150 + rnd() * 100, 30 + rnd() * 62, 12 + rnd() * 26, 5 + rnd() * 10, '#c99c6d', 0.12 + rnd() * 0.14);
  }
  // dark top ceiling
  for (let i = 0; i < 18; i++) {
    cloudBlob(ctx, rnd, rnd() * 240, rnd() * 22, 30 + rnd() * 40, 8 + rnd() * 12, '#070a0e', 0.48);
  }

  // distant jagged mountains
  const ridge = (baseY, color, amp, step) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(0, 135);
    for (let x = 0; x <= 240; x += step) {
      const y = baseY + Math.sin(x * 0.11) * amp + Math.sin(x * 0.037 + 2) * amp * 0.8 + rnd() * 2;
      ctx.lineTo(x, y);
    }
    ctx.lineTo(240, 135);
    ctx.closePath();
    ctx.fill();
  };
  ridge(96, '#5b554d', 5, 6);
  ridge(102, '#403b36', 6, 5);

  // temple silhouettes on the horizon (left)
  ctx.fillStyle = '#241f1d';
  for (const [bx, by, n, cw, chh] of [[26, 104, 5, 4, 24], [56, 99, 7, 3, 30], [150, 103, 4, 4, 22]]) {
    ctx.fillRect(bx - 3, by, n * (cw + 1) + 4, 3);
    for (let i = 0; i < n; i++) {
      const x = bx + i * (cw + 1);
      ctx.fillRect(x, by + 3, cw, chh);
      ctx.fillRect(x + cw / 2 - 0.5, by + 3, 1, chh);
    }
  }
  // ruined arches
  ctx.fillStyle = '#1a1614';
  ctx.beginPath();
  ctx.arc(120, 118, 12, Math.PI, Math.PI * 2);
  ctx.fillRect(108, 118, 3, 14);
  ctx.fillRect(129, 118, 3, 14);
  ctx.fill();

  // desolate ground haze
  const hz = ctx.createLinearGradient(0, 108, 0, 135);
  hz.addColorStop(0, 'rgba(10,8,8,0)');
  hz.addColorStop(1, 'rgba(6,5,6,0.95)');
  ctx.fillStyle = hz;
  ctx.fillRect(0, 104, 240, 31);

  quantize(c, SKY_PALETTE);
  return c;
}

