// ------------------------------------------------------------------ blades
function drawBlade(ctx, x0, y0, x1, y1, cx, cy, width, tipDelay = 1) {
  // sample a quadratic curve, build tapering metal bands
  const steps = 46;
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = (1 - t) * (1 - t) * x0 + 2 * (1 - t) * t * cx + t * t * x1;
    const y = (1 - t) * (1 - t) * y0 + 2 * (1 - t) * t * cy + t * t * y1;
    pts.push([x, y, t]);
  }
  for (let i = 0; i < steps; i++) {
    const [x, y, t] = pts[i];
    const [nx, ny] = pts[i + 1];
    const w = Math.max(1, width * (1 - t * 0.86) * (t < 0.06 ? 0.7 : 1));
    const dx = nx - x;
    const dy = ny - y;
    const len = Math.hypot(dx, dy) || 1;
    const pxr = (-dy / len) * w * 0.5;
    const pyr = (dx / len) * w * 0.5;
    // dark base
    fillPoly(ctx, [x - pxr, y - pyr, x + pxr, y + pyr, nx + pxr, ny + pyr, nx - pxr, ny - pyr], '#5d4327');
    // main metal
    fillPoly(ctx, [x - pxr * 0.7, y - pyr * 0.7, x + pxr * 0.7, y + pyr * 0.7, nx + pxr * 0.7, ny + pyr * 0.7, nx - pxr * 0.7, ny - pyr * 0.7], t > 0.55 ? '#b8894a' : '#8a6534');
    // bright edge
    fillPoly(ctx, [x - pxr * 0.6, y - pyr * 0.6, x - pxr * 0.15, y - pyr * 0.15, nx - pxr * 0.15, ny - pyr * 0.15, nx - pxr * 0.6, ny - pyr * 0.6], '#d9ac63');
    fillPoly(ctx, [x - pxr * 0.35, y - pyr * 0.35, x - pxr * 0.05, y - pyr * 0.05, nx - pxr * 0.05, ny - pyr * 0.05, nx - pxr * 0.35, ny - pyr * 0.35], '#f0cf8b');
  }
  // blood on the blade
  const rnd = mulberry32(Math.round(x1 + y1));
  for (let i = 0; i < 16; i++) {
    const t = 0.12 + rnd() * 0.6;
    const idx = Math.floor(t * steps);
    const [x, y] = pts[idx];
    const w = width * (1 - t * 0.86);
    ctx.fillStyle = rnd() < 0.5 ? '#5a1c18' : '#962a20';
    ctx.fillRect(Math.round(x + (rnd() - 0.5) * w * 0.6), Math.round(y + (rnd() - 0.5) * 3), 1 + Math.floor(rnd() * 3), 1 + Math.floor(rnd() * 3));
  }
  // hilt wrap
  const hx = (1 - 0.02) * (1 - 0.02) * x0 + 2 * 0.02 * 0.98 * cx + 0.0004 * x1;
  const hy = (1 - 0.02) * (1 - 0.02) * y0 + 2 * 0.02 * 0.98 * cy + 0.0004 * y1;
  disc(ctx, hx, hy, width * 0.5, '#3a281c');
  fillPoly(ctx, [hx - 4, hy + 2, hx + 4, hy + 2, hx + 3, hy + 12, hx - 3, hy + 12], '#2e2119');
  for (let i = 0; i < 5; i++) px(ctx, hx - 3, hy + 3 + i * 2, 6, 1, i % 2 ? '#94552c' : '#3a281c');
}

