    [cx + 4, cy - 8, 46, 24], [cx + 48, cy + 2, 38, 22], [cx + 84, cy + 12, 30, 18],
    [cx - 96, cy + 18, 26, 14], [cx - 30, cy + 18, 40, 16], [cx + 34, cy + 20, 30, 14],
  ];
  for (const [x, y, rx, ry] of lobes) {
    ctx.fillStyle = '#420b0c';
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
