  // splatters
  for (let i = 0; i < 90; i++) {
    const x = cx - 150 + rnd() * 320;
    const y = cy - 40 + rnd() * 82;
    const r = rnd() < 0.82 ? rnd() * 2.4 + 0.4 : 2 + rnd() * 4;
    ctx.fillStyle = rnd() < 0.55 ? '#841713' : '#570e0e';
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }
  // tendrils reaching left
  for (let i = 0; i < 7; i++) {
    const y = cy - 14 + rnd() * 34;
    const len = 40 + rnd() * 90;
    ctx.strokeStyle = '#570e0e';
    ctx.lineWidth = 1 + rnd() * 3;
    ctx.beginPath();
    ctx.moveTo(cx - 100, y);
    ctx.bezierCurveTo(cx - 140, y + (rnd() - 0.5) * 14, cx - 150 - len * 0.4, y + (rnd() - 0.5) * 20, cx - 120 - len, y + (rnd() - 0.5) * 26);
    ctx.stroke();
  }
  // drips
  for (let i = 0; i < 22; i++) {
    const x = cx - 132 + rnd() * 280;
    const y = cy + 10 + rnd() * 18;
    const len = 4 + rnd() * 30;
    ctx.fillStyle = rnd() < 0.5 ? '#6d1210' : '#4a0b0c';
    ctx.fillRect(x, y, 1 + (rnd() < 0.3 ? 2 : 1), len);
    if (rnd() < 0.5) {
      ctx.beginPath();
      ctx.arc(x + 1, y + len, 1.6 + rnd() * 1.6, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  // darker core for contrast behind letters
  for (let i = 0; i < 5; i++) {
    const x = cx - 90 + i * 46;
    const y = cy + 2 + Math.sin(i) * 6;
    ctx.fillStyle = '#2c0709';
    ctx.beginPath();
    ctx.ellipse(x, y, 30, 16, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // a couple of bright arterial flecks
  for (let i = 0; i < 18; i++) {
    const x = cx - 130 + rnd() * 280;
    const y = cy - 26 + rnd() * 70;
    ctx.fillStyle = '#b0261b';
    ctx.fillRect(x, y, 1 + Math.round(rnd() * 3), 1 + Math.round(rnd() * 2));
  }

  quantize(c, BANNER_PALETTE);
  return c;
}

// -------------------------------------------------------------- logo layer
function buildLogo() {
  const scale = 2;
  const w = logoWidth('GOD OF WAR', scale) + 8 + 8;
  const h = 9 * scale + 14;
  const c = makeCanvas(w + 40, h + 30);
  const ctx = c.getContext('2d');
  const x = 20;
  const y = 18;

  // shadow
  logoOutline(ctx, 'GOD OF WAR', x + 2, y + 3, scale, '#1a0507');

  // fill with vertical gold gradient + blood-soaked bottom
  const rows = [
    '#5a3a12', '#8a6430', '#c7a052', '#f0d38a', '#ffeab0', '#fff4cf',
    '#f7e0a4', '#dcb46a', '#c08d40', '#9a6726',
  ];
  drawLogo(ctx, 'GOD OF WAR', x, y, scale, rows);
  // top face highlight
  for (let i = 0; i < 9; i++) {
    // nothing: gradient already does it
  }
  // dark outline
  logoOutline(ctx, 'GOD OF WAR', x, y, scale, '#2a0709');
  drawLogo(ctx, 'GOD OF WAR', x, y, scale, rows);

  // III off to the right, like the third entry
  const iiiX = x + logoWidth('GOD OF WAR', scale) + 10;
  const iiiY = y + 8;
  const iiRows = ['#5a0d0d', '#7f1412', '#a51d17', '#7f1412', '#5a0d0d', '#3c0909', '#5a0d0d', '#7f1412', '#5a0d0d'];
  for (let i = 0; i < 3; i++) {
    drawLogo(ctx, 'I', iiiX + i * 12, iiiY, 1, iiRows.map((c2, r) => (r < 4 ? '#c43622' : c2)));
  }

  // blood spatter eating into the letters
  const rnd = mulberry32(777);
  for (let i = 0; i < 46; i++) {
    const sx = 22 + rnd() * (w - 20);
    const sy = 22 + rnd() * 20;
    ctx.fillStyle = rnd() < 0.4 ? '#962a20' : '#5a1c18';
    ctx.fillRect(sx, sy, 1 + Math.round(rnd() * 3), 1 + Math.round(rnd() * 2));
  }

  // scanline sheen (static here, animated on top)
  return c;
}

// ------------------------------------------------------------------- facade
export class TitleArt {
  constructor() {
    this.sky = buildSky();
    this.figure = buildKratos();
    this.blades = buildBlades();
    this.banner = buildBanner();
    this.logo = buildLogo();
    this.time = 0;
    this.flash = 0;
    this.nextBolt = 7 + Math.random() * 7;
    this.bolt = null;
    this.embers = Array.from({ length: 46 }, () => ({
      x: Math.random() * 480,
      y: 190 + Math.random() * 90,
      vy: 6 + Math.random() * 18,
      vx: -4 + Math.random() * 12,
      life: Math.random(),
      size: Math.random() < 0.8 ? 1 : 2,
    }));
    this.ash = Array.from({ length: 70 }, () => ({
      x: Math.random() * 480,
      y: Math.random() * 270,
      vy: 5 + Math.random() * 12,
      vx: -7 + Math.random() * 14,
      size: Math.random() < 0.85 ? 1 : 2,
      alpha: 0.15 + Math.random() * 0.4,
    }));
  }

  update(dt) {
    this.time += dt;
    this.flash = Math.max(0, this.flash - dt * 2.6);
    this.nextBolt -= dt;
    if (this.nextBolt <= 0) {
      this.nextBolt = 9 + Math.random() * 12;
      this.flash = 0.9;
      this.bolt = {
        seed: Math.random() * 1000,
        x: 300 + Math.random() * 80,
        life: 0.5,
      };
      this.onThunder?.();
    }
    if (this.bolt) {
      this.bolt.life -= dt;
      if (this.bolt.life <= 0) this.bolt = null;
    }
    for (const e of this.embers) {
      e.y -= e.vy * dt;
      e.x += e.vx * dt;
      if (e.y < 150) {
        e.y = 240 + Math.random() * 40;
        e.x = Math.random() * 480;
      }
    }
    for (const a of this.ash) {
      a.y += a.vy * dt;
      a.x += a.vx * dt;
      if (a.y > 275) { a.y = -6; a.x = Math.random() * 480; }
      if (a.x < -6) a.x = 486;
      if (a.x > 486) a.x = -6;
    }
  }

  drawBackground(ctx, t = this.time) {
    // sky (static at 2x pixel scale)
    ctx.drawImage(this.sky, 0, 0, 480, 270);

    // sun breathing
    ctx.save();
    ctx.globalAlpha = 0.10 + Math.sin(t * 0.7) * 0.03;
    glow(ctx, 452, 128, 60, '#ffdfae', 0.5, 5);
    ctx.restore();

    // drifting fog bands
    for (let i = 0; i < 5; i++) {
      const y = 150 + i * 22;
      const off = (t * (5 + i * 3)) % 560 - 40;
      ctx.save();
      ctx.globalAlpha = 0.05 + i * 0.012;
      ctx.fillStyle = '#9a8d82';
      ctx.beginPath();
      ctx.ellipse(off, y, 150, 9 + i * 2, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(off - 300, y + 4, 130, 8, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // lightning
    if (this.flash > 0.02) {
      ctx.save();
      ctx.globalAlpha = Math.min(0.55, this.flash * 0.5);
      ctx.fillStyle = '#dfe9ff';
      ctx.fillRect(0, 0, 480, 270);
      ctx.restore();
      if (this.bolt) {
        const rnd = mulberry32(Math.floor(this.bolt.seed));
        ctx.save();
        ctx.globalAlpha = clamp(this.bolt.life * 2, 0, 1);
        let x = this.bolt.x;
        let y = 0;
        ctx.fillStyle = '#eef5ff';
        while (y < 150) {
          const nx = x + (rnd() - 0.5) * 26;
          const ny = y + 8 + rnd() * 14;
          const steps = Math.ceil(Math.hypot(nx - x, ny - y));
          for (let s = 0; s < steps; s++) {
            const pxr = x + ((nx - x) * s) / steps;
            const pyr = y + ((ny - y) * s) / steps;
            ctx.fillRect(Math.round(pxr), Math.round(pyr), 1, 2);
            if (s % 4 === 0) ctx.fillRect(Math.round(pxr) + 1, Math.round(pyr), 1, 1);
          }
          x = nx;
          y = ny;
          if (y > 60 && rnd() < 0.35) break;
        }
        ctx.restore();
      }
    }

    // drifting ash
    for (const a of this.ash) {
      ctx.globalAlpha = a.alpha;
      ctx.fillStyle = '#b9a99a';
      ctx.fillRect(a.x | 0, a.y | 0, a.size, a.size);
    }
    ctx.globalAlpha = 1;
  }

  drawFigure(ctx) {
    ctx.drawImage(this.figure, 0, 0);
    ctx.drawImage(this.blades, 0, 0);

    // firelight on the blades
    const flick = 0.75 + Math.sin(this.time * 9) * 0.12 + Math.sin(this.time * 17.3) * 0.08;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    glow(ctx, 250, 250, 46, '#ff8a2a', 0.16 * flick, 6);
    glow(ctx, 306, 252, 38, '#ffab3c', 0.13 * flick, 6);
    // embers rising from the blades
    for (const e of this.embers) {
      if (e.y > 235) continue;
      const a = clamp((235 - e.y) / 90, 0, 1);
      ctx.globalAlpha = (0.25 + a * 0.55) * flick;
      ctx.fillStyle = a > 0.55 ? '#ffc46a' : '#e0622a';
      ctx.fillRect(e.x | 0, e.y | 0, e.size, e.size + 1);
    }
    ctx.restore();
  }

  drawBannerAndLogo(ctx) {
    ctx.drawImage(this.banner, 0, 0);
    // blood glow behind logo
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 0.10 + Math.sin(this.time * 1.4) * 0.03;
    glow(ctx, 160, 52, 110, '#c43622', 0.5, 5);
    ctx.restore();
    ctx.drawImage(this.logo, 30, 22);
    // "PIXEL EDITION" subtitle
    drawText(ctx, 'PIXEL EDITION', 168, 73, {
      scale: 1, color: '#e6c27c', spacing: 2, align: 'center',
      outline: '#1a0507', shadow: '#0a0203',
    });
    // thin blood underline
    ctx.fillStyle = '#5a0d0d';
    ctx.fillRect(96, 83, 146, 1);
    ctx.fillStyle = '#8a1613';
    ctx.fillRect(112, 84, 114, 1);
  }
}

// Bitmap-style physical input, touch buttons, and gamepad polling.
const KEYMAP = {
  left: ['ArrowLeft', 'KeyA'],
  right: ['ArrowRight', 'KeyD'],
  up: ['ArrowUp', 'KeyW'],
  down: ['ArrowDown', 'KeyS'],
  jump: ['Space', 'KeyW', 'ArrowUp'],
  attack: ['KeyJ', 'KeyX'],
  heavy: ['KeyK', 'KeyC'],
  rage: ['KeyL', 'KeyV'],
  dash: ['ShiftLeft', 'ShiftRight'],
  confirm: ['Enter', 'NumpadEnter', 'Space'],
  back: ['Escape', 'Backspace'],
  pause: ['Escape', 'KeyP'],
  credits: ['KeyC'],
};

const state = {
  down: new Set(),
  pressed: new Set(),
  pointer: { x: 240, y: 135, inside: false },
  clicks: [],
  touch: {},
};

function addPressed(action) {
  state.pressed.add(action);
}

const eventCodeToActions = new Map();
for (const [action, codes] of Object.entries(KEYMAP)) {
  for (const code of codes) {
    if (!eventCodeToActions.has(code)) eventCodeToActions.set(code, []);
    eventCodeToActions.get(code).push(action);
  }
}

export const input = {
  init(canvas) {
    window.addEventListener('keydown', (e) => {
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space', 'Tab'].includes(e.code)) e.preventDefault();
      if (e.repeat) return;
      const actions = eventCodeToActions.get(e.code) || [];
      for (const a of actions) {
        state.down.add(a);
        addPressed(a);
      }
    });
    window.addEventListener('keyup', (e) => {
      const actions = eventCodeToActions.get(e.code) || [];
      for (const a of actions) state.down.delete(a);
    });
    window.addEventListener('blur', () => {
      state.down.clear();
      for (const k of Object.keys(state.touch)) state.touch[k] = false;
    });

    const toCanvas = (ev) => {
      const r = canvas.getBoundingClientRect();
      return {
        x: ((ev.clientX - r.left) / r.width) * 480,
        y: ((ev.clientY - r.top) / r.height) * 270,
      };
    };
    canvas.addEventListener('pointermove', (ev) => {
      const p = toCanvas(ev);
      state.pointer.x = p.x;
      state.pointer.y = p.y;
      state.pointer.inside = true;
    });
    canvas.addEventListener('pointerleave', () => { state.pointer.inside = false; });
    canvas.addEventListener('pointerdown', (ev) => {
      ev.preventDefault();
      const p = toCanvas(ev);
      state.pointer.x = p.x;
      state.pointer.y = p.y;
      state.pointer.inside = true;
      state.clicks.push(p);
      addPressed('attack'); // gameplay: tap the canvas to attack
      addPressed('confirm');
    });
    canvas.addEventListener('contextmenu', (e) => e.preventDefault());

    // virtual touch buttons
    const buttons = document.querySelectorAll('[data-action]');
    for (const el of buttons) {
      const action = el.dataset.action;
      const on = (ev) => {
        ev.preventDefault();
        el.setPointerCapture?.(ev.pointerId);
        state.touch[action] = true;
        addPressed(action);
      };
      const off = (ev) => {
        ev.preventDefault();
        state.touch[action] = false;
      };
      el.addEventListener('pointerdown', on);
      el.addEventListener('pointerup', off);
      el.addEventListener('pointercancel', off);
      el.addEventListener('pointerleave', (ev) => {
        if (ev.buttons === 0) state.touch[action] = false;
      });
    }
    window.addEventListener('pointerup', () => {
      for (const k of Object.keys(state.touch)) state.touch[k] = false;
    });

    this.canvas = canvas;
    this.padPrev = {};
    this.padEnabled = true;
  },

  isDown(action) {
    return state.down.has(action) || !!state.touch[action];
  },

  justPressed(action) {
    return state.pressed.has(action);
  },

  consume(action) {
    state.pressed.delete(action);
  },

  consumeClick() {
    return state.clicks.shift() || null;
  },

  get pointer() { return state.pointer; },

  pollGamepad() {
    if (!navigator.getGamepads) return;
    const pads = navigator.getGamepads();
    let pad = null;
    for (const p of pads) if (p && p.connected) { pad = p; break; }
    if (!pad) return;
    const b = pad.buttons;
    const ax = pad.axes[0] || 0;
    const ay = pad.axes[1] || 0;
    const now = {
      left: !!(b[14]?.pressed) || ax < -0.45,
      right: !!(b[15]?.pressed) || ax > 0.45,
      up: !!(b[12]?.pressed) || ay < -0.55,
      down: !!(b[13]?.pressed) || ay > 0.55,
      attack: !!(b[0]?.pressed),
      jump: !!(b[2]?.pressed),
      dash: !!(b[1]?.pressed),
      rage: !!(b[3]?.pressed),
      confirm: !!(b[0]?.pressed) || !!(b[9]?.pressed),
      back: !!(b[1]?.pressed) || !!(b[8]?.pressed),
      pause: !!(b[9]?.pressed),
      heavy: !!(b[5]?.pressed) || !!(b[7]?.pressed),
      credits: false,
    };
    const prev = this.padPrev;
    for (const [action, on] of Object.entries(now)) {
      if (on && !prev[action]) addPressed(action);
      if (on) state.down.add(action);
      else state.down.delete(action);
    }
    this.padPrev = now;
  },

  endFrame() {
    state.pressed.clear();
    state.clicks.length = 0;
  },
};

// Title screen, options, treasures, credits.
import { drawText, px, disc, glow, clamp, measureText, W, H } from './pixel.js';
import { input } from './input.js';
import { Save, TREASURES } from './save.js';
import { TitleArt } from './titleArt.js';

const ITEMS = [
  { id: 'new', label: 'NEW GAME' },
  { id: 'load', label: 'LOAD GAME' },
  { id: 'options', label: 'OPTIONS' },
  { id: 'treasures', label: 'TREASURES' },
];

const OPTION_ROWS = [
  { key: 'volume', label: 'VOLUME', type: 'slider' },
  { key: 'shake', label: 'SCREEN SHAKE', type: 'toggle' },
  { key: 'blood', label: 'BLOOD', type: 'toggle' },
  { key: 'crt', label: 'CRT FILTER', type: 'toggle' },
  { key: 'reset', label: 'ERASE PROGRESS', type: 'action' },
];

const GOLD = '#d9ab5c';
const GOLD_DIM = '#8a6534';
const RED = '#8d1b18';
const RED_DIM = '#5a1d1c';
const CREAM = '#efe3cf';
const ASH = '#b9a99a';

function panel(ctx, x, y, w, h, title) {
  ctx.save();
  ctx.globalAlpha = 0.86;
  px(ctx, x, y, w, h, '#0a0709');
  ctx.globalAlpha = 1;
  px(ctx, x, y, w, 1, '#3a2420');
  px(ctx, x, y + h - 1, w, 1, '#241715');
  px(ctx, x, y, 1, h, '#3a2420');
  px(ctx, x + w - 1, y, 1, h, '#241715');
  px(ctx, x + 2, y + 2, w - 4, 1, '#1c1214');
  // corner studs
  for (const [cx, cy] of [[x, y], [x + w - 3, y], [x, y + h - 3], [x + w - 3, y + h - 3]]) {
    px(ctx, cx, cy, 3, 3, '#6b4a2e');
    px(ctx, cx + 1, cy + 1, 1, 1, GOLD_DIM);
  }
  if (title) {
    px(ctx, x + 10, y + 12, w - 20, 1, '#4a1a16');
    drawText(ctx, title, x + 14, y + 6, { scale: 2, color: GOLD, shadow: '#1a0507', spacing: 1 });
    px(ctx, x + 10, y + 30, w - 20, 1, '#4a1a16');
    px(ctx, x + 10, y + 31, 40, 1, '#8d1b18');
  }
  ctx.restore();
}

export class MenuScene {
  constructor(app) {
    this.app = app;
    this.art = new TitleArt();
    this.art.onThunder = () => app.audio.sfx('thunder');
    this.index = 0;
    this.mode = 'root';
    this.optIndex = 0;
    this.treasureIndex = 0;
    this.toast = null;
    this.toastT = 0;
    this.resetArmed = false;
    this.time = 0;
    this.itemFlash = 0;
    this.launching = false;
    this.splash = [];
    this.mouse = { x: -100, y: -100 };
    for (let i = 0; i < 26; i++) {
      this.splash.push({ x: Math.random() * W, y: Math.random() * H, vx: -8 + Math.random() * 16, vy: 4 + Math.random() * 20, life: Math.random() });
    }
    this.setupPointer();
  }

  setupPointer() {}

  itemRect(i) {
    return { x: 58, y: 122 + i * 22, w: 190, h: 16 };
  }

  optionRect(i) {
    return { x: 92, y: 84 + i * 24, w: 300, h: 20 };
  }

  saveExists() {
    return !!Save.progress.run;
  }

  say(text) {
    this.toast = text;
    this.toastT = 2.6;
  }

  move(delta) {
    const n = this.mode === 'root' ? ITEMS.length : this.mode === 'options' ? OPTION_ROWS.length : this.mode === 'treasures' ? TREASURES.length : 0;
    if (!n) return;
    if (this.mode === 'root') {
      this.index = (this.index + delta + n) % n;
      this.itemFlash = 1;
    } else if (this.mode === 'options') {
      this.optIndex = (this.optIndex + delta + n) % n;
      this.resetArmed = false;
      this.itemFlash = 1;
    } else if (this.mode === 'treasures') {
      this.treasureIndex = (this.treasureIndex + delta + n) % n;
      this.itemFlash = 1;
    }
    this.app.audio.sfx('move');
  }

  activateRoot() {
    const id = ITEMS[this.index].id;
    if (id === 'new') {
      this.launchNew();
    } else if (id === 'load') {
      if (!this.saveExists()) {
        this.say('NO SAVE DATA. START A NEW GAME.');
        this.app.audio.sfx('back');
      } else {
        this.app.audio.sfx('start');
        this.app.beginTransition(() => this.app.startGame({ resume: true }));
      }
    } else if (id === 'options') {
      this.mode = 'options';
      this.optIndex = 0;
      this.resetArmed = false;
      this.app.audio.sfx('select');
    } else if (id === 'treasures') {
      this.mode = 'treasures';
      this.treasureIndex = 0;
      this.app.audio.sfx('select');
    }
  }

  launchNew() {
    this.app.audio.sfx('start');
    this.app.beginTransition(() => this.app.startGame({ resume: false }));
    this.launching = true;
  }

  adjustOption(dir) {
    const row = OPTION_ROWS[this.optIndex];
    const s = Save.settings;
    if (row.type === 'slider') {
      const v = clamp(Math.round((s.volume + dir * 0.1) * 10) / 10, 0, 1);
      Save.setSetting('volume', v);
      this.app.audio.setVolume(v);
      this.app.audio.sfx('move');
    } else if (row.type === 'toggle') {
      Save.setSetting(row.key, !s[row.key]);
      this.applySettings();
      this.app.audio.sfx('select');
    } else if (row.type === 'action') {
      if (!this.resetArmed) {
        this.resetArmed = true;
        this.app.audio.sfx('back');
      } else {
        Save.reset();
        this.applySettings();
        this.resetArmed = false;
        this.say('PROGRESS ERASED.');
        this.app.audio.sfx('select');
      }
    }
  }

  applySettings() {
    const s = Save.settings;
    this.app.audio.setVolume(s.volume);
    document.body.classList.toggle('crt-on', !!s.crt);
    this.app.applySettings();
  }

  update(dt) {
    this.time += dt;
    this.art.update(dt);
    if (this.itemFlash > 0) this.itemFlash = Math.max(0, this.itemFlash - dt * 4);
    if (this.toastT > 0) {
      this.toastT -= dt;
      if (this.toastT <= 0) this.toast = null;
    }
    for (const s of this.splash) {
      s.x += s.vx * dt;
      s.y += s.vy * dt;
      if (s.y > H + 4) { s.y = -4; s.x = Math.random() * W; }
      if (s.x < -4) s.x = W + 4;
      if (s.x > W + 4) s.x = -4;
    }

    const ptr = input.pointer;
    this.mouse.x = ptr.x;
    this.mouse.y = ptr.y;

    if (input.justPressed('up')) this.move(-1);
    if (input.justPressed('down')) this.move(1);

    if (this.mode === 'root') {
      // hover
      if (ptr.inside) {
        for (let i = 0; i < ITEMS.length; i++) {
          const r = this.itemRect(i);
          if (ptr.x >= r.x - 14 && ptr.x <= r.x + r.w && ptr.y >= r.y - 4 && ptr.y <= r.y + r.h) {
            if (this.index !== i) {
              this.index = i;
              this.itemFlash = 1;
              this.app.audio.sfx('move');
            }
            break;
          }
        }
      }
      const click = input.consumeClick();
      if (click) {
        for (let i = 0; i < ITEMS.length; i++) {
          const r = this.itemRect(i);
          if (click.x >= r.x - 14 && click.x <= r.x + r.w && click.y >= r.y - 4 && click.y <= r.y + r.h) {
            this.index = i;
            this.activateRoot();
            break;
          }
        }
      }
      if (input.justPressed('confirm') && !this.launching) {
        // ignore confirm generated by the same click that hovered nothing
        this.activateRoot();
      }
      if (input.justPressed('credits')) {
        this.mode = 'credits';
        this.app.audio.sfx('select');
      }
    } else if (this.mode === 'options') {
      if (input.justPressed('left')) this.adjustOption(-1);
      if (input.justPressed('right')) this.adjustOption(1);
      if (input.justPressed('confirm')) this.adjustOption(1);
      const click = input.consumeClick();
      if (click) {
        for (let i = 0; i < OPTION_ROWS.length; i++) {
          const r = this.optionRect(i);
          if (click.y >= r.y - 4 && click.y <= r.y + r.h) {
            this.optIndex = i;
            this.adjustOption(1);
            break;
          }
        }
      }
      if (input.justPressed('back')) {
        this.mode = 'root';
        this.resetArmed = false;
        this.app.audio.sfx('back');
      }
    } else if (this.mode === 'treasures') {
      const click = input.consumeClick();
      if (click) {
        for (let i = 0; i < TREASURES.length; i++) {
          const y = 86 + i * 26;
          if (click.y >= y - 4 && click.y <= y + 22) this.treasureIndex = i;
        }
      }
      if (input.justPressed('back') || input.justPressed('confirm')) {
        this.mode = 'root';
        this.app.audio.sfx('back');
      }
    } else if (this.mode === 'credits') {
      if (input.justPressed('back') || input.justPressed('confirm')) {
        this.mode = 'root';
        this.app.audio.sfx('back');
      }
    }

    if (this.mode !== 'root') input.consumeClick();
  }

  drawMenuItems(ctx) {
    const menuGlow = 0.5 + Math.sin(this.time * 1.8) * 0.08;
    ctx.save();
    ctx.globalAlpha = 0.72;
    const g = ctx.createLinearGradient(20, 0, 330, 0);
    g.addColorStop(0, 'rgba(4,3,4,0.86)');
    g.addColorStop(0.62, 'rgba(6,4,5,0.55)');
    g.addColorStop(1, 'rgba(8,5,6,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 92, 340, 132);
    ctx.restore();

    for (let i = 0; i < ITEMS.length; i++) {
      const r = this.itemRect(i);
      const sel = i === this.index;
      const y = r.y;
      if (sel) {
        // blood smear behind selection
        ctx.save();
        ctx.globalAlpha = 0.6;
        ctx.fillStyle = '#4a0b0c';
        ctx.beginPath();
        ctx.ellipse(r.x + 62, y + 8, 78, 10, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = 0.16 * menuGlow;
        glow(ctx, r.x + 56, y + 8, 40, '#ff5a32', 0.5, 4);
        ctx.restore();
        // marker
        const bob = Math.round(Math.sin(this.time * 5) * 1);
        px(ctx, r.x - 20, y + 4 + bob, 3, 3, '#c43622');
        px(ctx, r.x - 17, y + 6 + bob, 4, 2, '#8d1b18');
        px(ctx, r.x - 21, y + 6 + bob, 2, 1, '#8d1b18');
        // underline
        px(ctx, r.x - 2, y + 16, 84 + (this.itemFlash > 0.6 ? 8 : 0), 1, '#6d1210');
        drawText(ctx, ITEMS[i].label, r.x, y, {
          scale: 2,
          color: this.index === i && this.itemFlash > 0.65 ? '#fff6e2' : CREAM,
          outline: '#180606',
          shadow: '#7e1913',
          spacing: 1,
        });
      } else {
        drawText(ctx, ITEMS[i].label, r.x, y, {
          scale: 2,
          color: '#7c2c26',
          outline: '#160708',
          spacing: 1,
        });
      }
      if (i === 1) {
        const run = Save.progress.run;
        const label = run ? `WAVE ${run.wave}` : '';
        if (label) drawText(ctx, label, r.x + 160, y + 3, { scale: 1, color: '#6b5b4c', spacing: 1 });
      }
    }
  }

  drawFooter(ctx) {
    const y = 238;
    // X button
    disc(ctx, 64, y + 4, 5, '#3a2420');
    disc(ctx, 64, y + 4, 4, '#21171a');
    drawText(ctx, 'X', 61, y + 1, { scale: 1, color: '#d8c4a6' });
    drawText(ctx, 'SELECT', 74, y, { scale: 1, color: ASH, spacing: 1 });
    drawText(ctx, '\u2191\u2193 MOVE', 132, y, { scale: 1, color: '#6b5b4c', spacing: 1 });
    drawText(ctx, 'ENTER CONFIRM', 202, y, { scale: 1, color: '#6b5b4c', spacing: 1 });
    drawText(ctx, 'C CREDITS', 314, y, { scale: 1, color: '#5a4a40', spacing: 1 });

    drawText(ctx, 'V1.0 \u00b7 ASHES OF OLYMPUS', 470, 257, { scale: 1, color: '#5a4a40', spacing: 1, align: 'right' });
    if (this.app.isTouch) {
      drawText(ctx, 'TOQUE PARA ESCOLHER', 240, 250, { scale: 1, color: '#5a4a40', spacing: 1, align: 'center' });
    }
  }

  drawOptions(ctx) {
    panel(ctx, 70, 36, 340, 188, 'OPTIONS');
    const s = Save.settings;
    for (let i = 0; i < OPTION_ROWS.length; i++) {
      const row = OPTION_ROWS[i];
      const r = this.optionRect(i);
      const sel = i === this.optIndex;
      if (sel) {
        px(ctx, r.x - 6, r.y - 3, (r.w + 12) * 0.7, r.h + 2, '#2a0d0c');
        px(ctx, r.x - 6, r.y - 3, 2, r.h + 2, '#a3221b');
        drawText(ctx, '\u25c6', r.x - 16, r.y + 2, { scale: 1, color: '#c43622' });
      }
      drawText(ctx, row.label, r.x + 4, r.y + 2, {
        scale: 2,
        color: sel ? CREAM : '#8a6a58',
        outline: '#120606',
        spacing: 1,
      });
      let val = '';
      if (row.key === 'volume') {
        const filled = Math.round(s.volume * 10);
        for (let k = 0; k < 10; k++) {
          px(ctx, 292 + k * 9, r.y + 6, 6, 6, k < filled ? '#b0261b' : '#2a2020');
          if (k < filled) px(ctx, 292 + k * 9, r.y + 6, 6, 2, '#d64d2c');
        }
        val = `${Math.round(s.volume * 100)}`;
        drawText(ctx, val, 402, r.y + 2, { scale: 2, color: sel ? GOLD : GOLD_DIM, spacing: 1, align: 'right' });
      } else if (row.type === 'toggle') {
        val = s[row.key] ? 'ON' : 'OFF';
        drawText(ctx, val, 402, r.y + 2, {
          scale: 2,
          color: s[row.key] ? '#c98a3e' : '#5a4a44',
          spacing: 1,
          align: 'right',
        });
      } else if (row.type === 'action') {
        drawText(ctx, this.resetArmed ? 'SURE?' : 'RESET', 402, r.y + 2, {
          scale: 2,
          color: this.resetArmed ? '#d64d2c' : '#7c2c26',
          spacing: 1,
          align: 'right',
        });
      }
    }
    drawText(ctx, 'LEFT/RIGHT ADJUST  \u00b7  ESC BACK', 240, 206, { scale: 1, color: '#6b5b4c', spacing: 1, align: 'center' });
    if (this.resetArmed) {
      drawText(ctx, 'PRESS AGAIN TO ERASE ALL RECORDS', 240, 214, { scale: 1, color: '#b0261b', spacing: 1, align: 'center' });
    }
  }

  drawTreasures(ctx) {
    panel(ctx, 46, 34, 388, 204, 'TREASURES');
    const unlocked = new Set(Save.progress.unlocked);
    const kills = Save.progress.kills;
    for (let i = 0; i < TREASURES.length; i++) {
      const t = TREASURES[i];
      const y = 80 + i * 21;
      const sel = i === this.treasureIndex;
      const open = t.always || unlocked.has(t.id) || (t.id === 'centurion' && kills >= 25);
      if (sel) {
        px(ctx, 58, y - 3, 364, 19, '#2a0d0c');
        px(ctx, 58, y - 3, 2, 19, '#a3221b');
      }
      // relic medallion
      disc(ctx, 70, y + 5, 5, open ? '#4a2c16' : '#1c1719');
      disc(ctx, 70, y + 5, 3, open ? '#b8894a' : '#2c2426');
      if (open) px(ctx, 69, y + 4, 2, 2, '#f0cf8b');
      drawText(ctx, open ? t.name : '? ? ?', 82, y, {
        scale: 2,
        color: open ? (sel ? CREAM : '#b9a99a') : '#4a3c3a',
        outline: '#100506',
        spacing: 1,
      });
      if (open) drawText(ctx, 'UNLOCKED', 412, y + 3, { scale: 1, color: '#8a6534', spacing: 1, align: 'right' });
    }
    const t = TREASURES[this.treasureIndex];
    const open = t.always || unlocked.has(t.id) || (t.id === 'centurion' && kills >= 25);
    px(ctx, 58, 208, 364, 1, '#33201c');
    const desc = open ? t.desc : 'Continue lutando para revelar esta reliquia.';
    drawText(ctx, desc, 240, 214, { scale: 1, color: '#8a7a68', spacing: 1, align: 'center' });
    drawText(ctx, 'ESC BACK', 240, 228, { scale: 1, color: '#5a4a40', spacing: 1, align: 'center' });
  }

  drawCredits(ctx) {
    panel(ctx, 84, 52, 312, 160, 'CREDITS');
    const lines = [
      ['ASHES OF OLYMPUS', GOLD],
      ['A FAN-MADE PIXEL TRIBUTE', ASH],
      ['INSPIRED BY GOD OF WAR III', '#7c2c26'],
      ['', ASH],
      ['CODE + PIXEL ART + SOUND', CREAM],
      ['BUILT WITH VANILLA CANVAS', ASH],
      ['', ASH],
      ['ALL ASSETS GENERATED IN CODE', '#6b5b4c'],
      ['NO EXTERNAL SPRITES OR AUDIO', '#6b5b4c'],
    ];
    lines.forEach(([txt, color], i) => {
      drawText(ctx, txt, 240, 80 + i * 11, { scale: 1, color, spacing: 1, align: 'center' });
    });
    drawText(ctx, 'ESC / ENTER BACK', 240, 196, { scale: 1, color: '#5a4a40', spacing: 1, align: 'center' });
  }

  drawToast(ctx) {
    if (!this.toast) return;
    const w = measureText(this.toast, 1, 1) + 20;
    const x = 240 - w / 2;
    px(ctx, x, 214, w, 15, 'rgba(10,4,4,0.94)');
    px(ctx, x, 214, w, 1, '#7c2c26');
    px(ctx, x, 228, w, 1, '#3a1512');
    drawText(ctx, this.toast, 240, 218, { scale: 1, color: '#e2b27a', spacing: 1, align: 'center' });
  }

  render(ctx) {
    const t = this.time;
    this.art.drawBackground(ctx, t);
    this.art.drawFigure(ctx);

    // drifting cinders over the figure
    for (const s of this.splash) {
      ctx.globalAlpha = 0.22 + (s.life * 0.3);
      ctx.fillStyle = '#c9a37a';
      ctx.fillRect(s.x | 0, s.y | 0, 1, 1);
    }
    ctx.globalAlpha = 1;

    this.art.drawBannerAndLogo(ctx);

    if (this.mode === 'root') {
      this.drawMenuItems(ctx);
      this.drawFooter(ctx);
    } else if (this.mode === 'options') {
      this.drawOptions(ctx);
    } else if (this.mode === 'treasures') {
      this.drawTreasures(ctx);
    } else if (this.mode === 'credits') {
      this.drawCredits(ctx);
    }
    this.drawToast(ctx);
  }
}

// Battlefield backdrop and all character rendering, drawn with chunky rectangles.
import { makeCanvas, px, disc, glow, fillPoly, quantize, mulberry32, clamp } from './pixel.js';

export const GROUND_Y = 228;

const BG_PALETTE = [
  '#05060a', '#080a0f', '#0c0f15', '#11151c', '#171c24', '#1e242d',
  '#262d37', '#303842', '#3b434d', '#48505a', '#575e66', '#676b70',
  '#7a7268', '#8d8072', '#a4947e', '#b8a48a', '#cbb694', '#dcc7a2',
  '#eed7ae', '#f7e6c2', '#5a2c1c', '#33150f', '#6d2a18', '#8f3a20',
  '#2a2118', '#3d2f22', '#1a1410', '#100c0a', '#211a1b', '#2c2320',
];

// ------------------------------------------------------------------ helpers
export function line(ctx, x0, y0, x1, y1, color, w = 1) {
  x0 = Math.round(x0); y0 = Math.round(y0); x1 = Math.round(x1); y1 = Math.round(y1);
  ctx.fillStyle = color;
  let dx = Math.abs(x1 - x0);
  let sx = x0 < x1 ? 1 : -1;
  let dy = -Math.abs(y1 - y0);
  let sy = y0 < y1 ? 1 : -1;
  let err = dx + dy;
  let guard = 300;
  while (guard-- > 0) {
    ctx.fillRect(x0, y0, w, w);
    if (x0 === x1 && y0 === y1) break;
    const e2 = 2 * err;
    if (e2 >= dy) { err += dy; x0 += sx; }
    if (e2 <= dx) { err += dx; y0 += sy; }
  }
}

function limb(ctx, x0, y0, x1, y1, color, w, outline) {
  if (outline) line(ctx, x0, y0, x1, y1, outline, w + 2);
  line(ctx, x0, y0, x1, y1, color, w);
}

// ------------------------------------------------------------ arena backdrop
export function buildArenaBackdrop() {
  const c = makeCanvas(480, 270);
  const ctx = c.getContext('2d');
  const rnd = mulberry32(2024);

  const sky = ctx.createLinearGradient(0, 0, 0, 240);
  sky.addColorStop(0, '#080b11');
  sky.addColorStop(0.3, '#141a23');
  sky.addColorStop(0.5, '#2a2c30');
  sky.addColorStop(0.66, '#614a36');
  sky.addColorStop(0.78, '#9a6c42');
  sky.addColorStop(0.86, '#3b2a1d');
  sky.addColorStop(1, '#0e0b09');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, 480, 270);

  // storm cells
  for (let i = 0; i < 40; i++) {
    ctx.save();
    ctx.globalAlpha = 0.18 + rnd() * 0.22;
    ctx.fillStyle = rnd() < 0.5 ? '#0a0d12' : '#39424c';
    ctx.beginPath();
    ctx.ellipse(rnd() * 480, rnd() * 120, 40 + rnd() * 80, 10 + rnd() * 20, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
  // glow on the horizon behind Olympus
  const sun = ctx.createRadialGradient(238, 166, 4, 238, 166, 130);
  sun.addColorStop(0, 'rgba(255,220,160,0.7)');
  sun.addColorStop(0.35, 'rgba(226,150,86,0.22)');
  sun.addColorStop(1, 'rgba(160,80,40,0)');
  ctx.fillStyle = sun;
  ctx.fillRect(80, 60, 320, 180);

  // distant mount Olympus
  fillPoly(ctx, [40, 216, 96, 160, 138, 186, 196, 108, 244, 178, 300, 142, 350, 188, 404, 152, 480, 216], '#211d21');
  fillPoly(ctx, [150, 196, 196, 118, 224, 150, 244, 128, 282, 196], '#2a2426');
  // temple silhouette atop the peak
  ctx.fillStyle = '#1b171a';
  ctx.fillRect(176, 112, 44, 4);
  for (let i = 0; i < 6; i++) ctx.fillRect(178 + i * 7, 116, 4, 24);
  ctx.fillRect(172, 140, 52, 3);
  // tiny warm windows
  for (let i = 0; i < 5; i++) px(ctx, 181 + i * 7, 124 + (i % 2) * 4, 2, 3, '#a2602e');

  // ruined giant statue, half buried in fog
  ctx.save();
  ctx.globalAlpha = 0.9;
  fillPoly(ctx, [180, 228, 190, 180, 204, 168, 206, 152, 218, 148, 222, 132, 236, 128, 244, 140, 250, 160, 262, 172, 270, 196, 276, 228], '#181419');
  const stRnd = mulberry32(77);
  for (let i = 0; i < 12; i++) {
    px(ctx, 200 + stRnd() * 60, 140 + stRnd() * 80, 2, 8 + stRnd() * 14, '#221c20');
  }
  px(ctx, 228, 146, 5, 3, '#8f3a20');
  px(ctx, 242, 146, 4, 3, '#8f3a20');
  ctx.restore();

  // broken columns, mid ground
  const column = (x, top, h, w) => {
    ctx.fillStyle = '#2b2325';
    ctx.fillRect(x, top, w, h);
    ctx.fillStyle = '#3d2f2c';
    ctx.fillRect(x + 2, top, 4, h);
    ctx.fillStyle = '#1a1415';
    ctx.fillRect(x + w - 5, top, 4, h);
    ctx.fillStyle = '#463833';
    for (let i = 1; i < w - 2; i += 5) ctx.fillRect(x + i, top + 2, 1, h - 2);
    // capital
    ctx.fillStyle = '#3b302b';
    ctx.fillRect(x - 4, top - 7, w + 8, 6);
    ctx.fillRect(x - 6, top - 2, w + 12, 3);
    ctx.fillStyle = '#241c1a';
    ctx.fillRect(x - 4, top - 8, w + 8, 2);
    // erosion at top
    ctx.fillStyle = '#0c0909';
    ctx.fillRect(x + w * 0.2, top - 8, 4, 4);
    ctx.fillRect(x + w * 0.7, top - 6, 3, 3);
  };
  column(24, 100, 128, 26);
  column(56, 132, 96, 18);
  column(420, 88, 140, 26);
  column(388, 138, 90, 16);
  column(348, 158, 70, 12);

  // chain hanging between columns (visual flavour)
  ctx.fillStyle = '#171214';
  for (let i = 0; i < 40; i++) {
    const t = i / 39;
    const x = 56 + t * 330;
    const y = 112 + Math.sin(t * Math.PI) * 34;
    ctx.fillRect(Math.round(x), Math.round(y), 2, 4);
    ctx.fillRect(Math.round(x + 1), Math.round(y + 1), 1, 1);
  }

  // smoke hugging the ground
  for (let i = 0; i < 26; i++) {
    ctx.save();
    ctx.globalAlpha = 0.1 + rnd() * 0.12;
    ctx.fillStyle = i % 3 ? '#3b3430' : '#5b4a3c';
    ctx.beginPath();
    ctx.ellipse(rnd() * 480, 196 + rnd() * 46, 30 + rnd() * 60, 6 + rnd() * 10, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // floor slab
  ctx.fillStyle = '#1a1410';
  ctx.fillRect(0, GROUND_Y, 480, 270 - GROUND_Y);
  ctx.fillStyle = '#2a2118';
  ctx.fillRect(0, GROUND_Y, 480, 5);
  ctx.fillStyle = '#3d2f22';
  ctx.fillRect(0, GROUND_Y, 480, 1);
  ctx.fillStyle = '#4a3a28';
  for (let x = 6; x < 480; x += 46) ctx.fillRect(x, GROUND_Y + 1, 18, 1);
  // tiles
  for (let y = GROUND_Y + 8; y < 270; y += 12) {
    for (let x = (y / 12) % 2 ? 12 : -8; x < 480; x += 52) {
      px(ctx, x, y, 46, 1, '#2b2017');
      px(ctx, x, y + 1, 1, 10, '#140f0c');
      px(ctx, x + 6, y + 3, 20, 1, '#241a13');
    }
  }
  // cracks
  const cr = mulberry32(567);
  for (let i = 0; i < 10; i++) {
    let x = cr() * 480;
    let y = GROUND_Y + 10 + cr() * 30;
    for (let s = 0; s < 9; s++) {
      px(ctx, x, y, 1, 1, '#0d0a08');
      x += -2 + cr() * 5;
      y += cr() * 2;
    }
  }
  // ash drifts on the floor
  for (let i = 0; i < 90; i++) {
    px(ctx, cr() * 480, GROUND_Y + 4 + cr() * 38, 1, 1, cr() < 0.5 ? '#3a2f24' : '#241c15');
  }

  // foreground framing rocks / broken pillars at the very edges
  ctx.fillStyle = '#0d0a09';
  fillPoly(ctx, [0, 270, 0, 214, 10, 206, 18, 226, 26, 270], '#151011');
  fillPoly(ctx, [480, 270, 480, 208, 468, 200, 458, 226, 452, 270], '#151011');
  px(ctx, 3, 214, 6, 2, '#3b302b');
  px(ctx, 464, 204, 8, 2, '#3b302b');

  quantize(c, BG_PALETTE);
  return c;
}

// ------------------------------------------------------------------- Kratos
const SKIN = '#c9b39e';
const SKIN_D = '#8b7563';
const SKIN_DD = '#5c4a3f';
const SKIN_H = '#eddcc3';
const LEATHER = '#3a2a24';
const LEATHER_L = '#5a4133';
const RED = '#a3221b';
const RED_D = '#6d1210';
const GOLD = '#d9ac63';
const GOLD_H = '#f8e6b4';
const STEEL = '#e6d3a5';
const STEEL_H = '#fffbee';
const STEEL_D = '#9c7228';
const DARK = '#1a1214';

function bladeShape(ctx, hx, hy, angle, len, flick = 0) {
  const tx = hx + Math.cos(angle) * len;
  const ty = hy + Math.sin(angle) * len;
  const nx = -Math.sin(angle);
  const ny = Math.cos(angle);
  const w = 2.6;
  // dark spine
  fillPoly(ctx, [hx + nx * w, hy + ny * w, tx - nx * 1.2, ty - ny * 1.2, tx + nx * 1.2, ty + ny * 1.2, hx - nx * w, hy - ny * w], DARK);
  // metal
  fillPoly(ctx, [hx + nx * (w - 0.8), hy + ny * (w - 0.8), tx, ty, hx + nx * 1.4, hy + ny * 1.4], STEEL_D);
  fillPoly(ctx, [hx + nx * 1.4, hy + ny * 1.4, tx, ty, hx - nx * 0.8, hy - ny * 0.8], STEEL);
  // hot edge
  line(ctx, hx + nx * 1.6, hy + ny * 1.6, tx, ty, STEEL_H, 1);
  // blood along the blade
  const bx = hx + (tx - hx) * 0.45;
  const by = hy + (ty - hy) * 0.45;
  px(ctx, bx, by, 2, 2, RED_D);
  px(ctx, bx + 2, by - 2, 2, 1, RED);
  // flame licking off the tip
  if (flick > 0) {
    const fl = 2 + flick * 3;
    px(ctx, tx + (Math.random() - 0.5) * 2, ty - fl, 1, fl + 1, '#ff9d3a');
    px(ctx, tx - 1, ty - fl - 2, 1, 2, '#ffd27a');
  }
}

export function drawKratos(ctx, p, time) {
  const speed = p.state === 'run';
  const attacking = p.state === 'attack';
  const heavy = p.state === 'heavy';
  const hurt = p.state === 'hurt';
  const dead = p.state === 'dead';
  const dash = p.state === 'dash';
  const air = !p.onGround;

  ctx.save();
  ctx.translate(Math.round(p.x), Math.round(p.y));
  ctx.scale(p.facing, 1);
  const blink = p.invuln > 0 && Math.floor(time * 40) % 2 === 0 && !dead;
  if (blink) ctx.globalAlpha = 0.5;

  const bob = !air && !speed && !attacking ? Math.round(Math.sin(time * 3) * 0.7) : 0;
  const lean = speed ? 2 : dash ? 4 : attacking ? 1 : 0;
  const crouch = dead ? 8 : dash ? 4 : 0;
  ctx.translate(0, bob + crouch);

  // --- legs
  const phase = p.walkPhase;
  let lfx = -5, lfy = 0, rfx = 5, rfy = 0;
  if (speed) {
    lfx = -5 + Math.sin(phase) * 4;
    rfx = 5 - Math.sin(phase) * 4;
    lfy = Math.max(0, -Math.sin(phase) * 4);
    rfy = Math.max(0, Math.sin(phase) * 4);
  } else if (air) {
    lfx = -6; lfy = 4; rfx = 6; rfy = 1;
  } else if (dash) {
    lfx = -9; rfx = 7;
  } else if (attacking || heavy) {
    lfx = -8; rfx = 6;
  }
  if (dead) { lfx = -10; rfx = 4; lfy = 6; rfy = 5; }

  // rear leg
  limb(ctx, -3, -16, lfx - 1, -6, LEATHER, 4, DARK);
  limb(ctx, lfx - 1, -6, lfx, 0 - lfy, LEATHER, 3, DARK);
  px(ctx, lfx - 2, -1 - lfy, 5, 2, '#221a16');
  // front leg
  limb(ctx, 3, -16, rfx + 1, -6, LEATHER_L, 4, DARK);
  limb(ctx, rfx + 1, -6, rfx + (speed ? Math.sin(phase) * 1 : 0), 0 - rfy, LEATHER_L, 3, DARK);
  px(ctx, rfx - 1, -1 - rfy, 5, 2, '#2c221c');
  // gold greave highlights
  px(ctx, rfx - 1, -8 - rfy, 3, 1, GOLD);
  px(ctx, lfx - 1, -8 - lfy, 3, 1, STEEL_D);

  // --- skirt / loincloth
  for (let i = -4; i <= 4; i++) {
    const h = 8 + ((i * 7) % 3);
    px(ctx, i * 2 - 1, -22, 2, h, i % 2 ? LEATHER : '#4a1a16');
  }
  px(ctx, -8, -24, 16, 3, RED_D);
  px(ctx, -8, -24, 16, 1, '#c43622');
  px(ctx, -2, -24, 3, 2, GOLD);

  // --- torso
  px(ctx, -8 + lean, -36, 17, 14, SKIN);
  px(ctx, -8 + lean, -36, 4, 14, SKIN_H);
  px(ctx, -8 + lean, -24, 17, 2, SKIN_D);
  // chest shadow + abs suggestion
  px(ctx, 2 + lean, -33, 6, 9, SKIN_D);
  px(ctx, -1 + lean, -29, 6, 1, SKIN_D);
  px(ctx, -1 + lean, -26, 6, 1, SKIN_D);
  // red war paint
  px(ctx, -6 + lean, -34, 3, 9, RED);
  px(ctx, -6 + lean, -34, 1, 9, '#cf5138');
  px(ctx, -3 + lean, -28, 4, 2, RED);
  // belt
  px(ctx, -9 + lean, -23, 18, 3, '#2b1c16');
  px(ctx, -9 + lean, -23, 18, 1, '#6b4a2e');
  px(ctx, 2 + lean, -22, 4, 2, GOLD);
  px(ctx, 3 + lean, -22, 2, 1, GOLD_H);

  // --- shoulders
  // back shoulder
  px(ctx, -12 + lean, -37, 7, 8, SKIN_D);
  px(ctx, -12 + lean, -37, 2, 8, SKIN_DD);
  // front pauldron
  px(ctx, 4 + lean, -39, 9, 8, '#3a2a1e');
  px(ctx, 4 + lean, -39, 9, 2, GOLD);
  px(ctx, 4 + lean, -38, 2, 6, GOLD_H);
  px(ctx, 11 + lean, -36, 2, 4, STEEL_D);
  // spine tattoo / ash
  px(ctx, -2 + lean, -36, 1, 4, '#d8c4ab');

  // --- head
  const headX = 0 + lean;
  const headY = -49;
  px(ctx, headX - 4, headY, 9, 9, SKIN);
  px(ctx, headX - 4, headY, 3, 9, SKIN_H);
  px(ctx, headX + 3, headY + 2, 2, 6, SKIN_D);
  // beard
  px(ctx, headX - 4, headY + 7, 9, 3, '#2f282a');
  px(ctx, headX - 4, headY + 9, 6, 2, '#3a3233');
  px(ctx, headX - 3, headY + 7, 7, 1, '#4a4242');
  // tattoo stripe over the left eye
  px(ctx, headX - 1, headY - 1, 2, 6, RED);
  px(ctx, headX - 1, headY + 1, 1, 4, '#cf5138');
  px(ctx, headX + 1, headY + 6, 2, 2, RED_D);
  // eye + brow
  px(ctx, headX + 1, headY + 3, 3, 1, DARK);
  px(ctx, headX + 2, headY + 4, 2, 1, '#f0dfc9');
  px(ctx, headX + 3, headY + 4, 1, 1, '#1a1214');
  // skull shading, scar
  px(ctx, headX + 3, headY + 1, 1, 3, SKIN_D);
  px(ctx, headX - 3, headY + 2, 1, 1, '#5a1c18');
  px(ctx, headX - 2, headY + 4, 1, 2, '#5a1c18');

  // --- arms + blades
  const shoulder = { x: 7 + lean, y: -35 };
  let handF = { x: 12, y: -26 };
  let handB = { x: -10, y: -26 };
  let angF = 1.5;
  let angB = 2.3;
  const flick = attacking || heavy ? 1 : 0;

  if (attacking) {
    const ap = clamp(p.attackT / p.attackDur, 0, 1);
    const swing = Math.sin(ap * Math.PI);
    if (p.attackStep === 0) {
      handF = { x: 12 + swing * 12, y: -30 - swing * 2 };
      angF = -0.5 + swing * 1.6;
      handB = { x: -9, y: -24 };
      angB = 2.4;
    } else if (p.attackStep === 1) {
      handF = { x: 9 - swing * 2, y: -42 - swing * 2 };
      angF = -1.9 + swing * 2.6;
      handB = { x: -10 - swing * 6, y: -30 };
      angB = 3.6 - swing * 1.2;
    } else {
      handF = { x: 11 + swing * 14, y: -27 - swing * 4 };
      angF = -0.9 + swing * 2.2;
      handB = { x: 4 + swing * 10, y: -32 - swing * 6 };
      angB = -1.1 + swing * 2.0;
    }
  } else if (heavy) {
    const ap = clamp(p.attackT / p.attackDur, 0, 1);
    const raise = Math.min(1, ap * 2.6);
    const slam = Math.max(0, (ap - 0.42) * 2.2);
    handF = { x: 9 + slam * 8, y: -38 - raise * 10 + slam * 25 };
    angF = raise > 0.75 ? 1.4 + slam * 1.2 : -1.2;
    handB = { x: 2 + slam * 6, y: -36 - raise * 8 + slam * 22 };
    angB = raise > 0.75 ? 1.2 + slam * 1.3 : -1.5;
  } else if (air) {
    handF = { x: 13, y: -34 };
    angF = -0.2;
    handB = { x: -13, y: -34 };
    angB = 3.4;
  } else if (speed) {
    handF = { x: 13, y: -24 - Math.sin(phase) * 2 };
    angF = 2.1;
    handB = { x: -12, y: -24 + Math.sin(phase) * 2 };
    angB = 2.7;
  } else if (dead) {
    handF = { x: 11, y: -8 };
    angF = 1.7;
    handB = { x: -12, y: -10 };
    angB = 2.1;
  } else if (hurt) {
    handF = { x: 14, y: -32 };
    angF = 2.3;
    handB = { x: -11, y: -30 };
    angB = 2.9;
  }

  // back arm first
  limb(ctx, shoulder.x - 12, shoulder.y - 1, handB.x, handB.y, SKIN_D, 3, DARK);
  px(ctx, handB.x - 2, handB.y - 2, 4, 4, LEATHER);
  px(ctx, handB.x - 2, handB.y - 2, 4, 1, '#7c4a2a');
  bladeShape(ctx, handB.x, handB.y, angB, 20, flick * 0.6);

  // front arm
  limb(ctx, shoulder.x, shoulder.y, handF.x, handF.y, SKIN, 4, DARK);
  px(ctx, handF.x - 1, handF.y - 2, 4, 4, LEATHER_L);
  px(ctx, handF.x - 1, handF.y - 2, 4, 1, '#8a5a34');
  bladeShape(ctx, handF.x, handF.y, angF, 23, flick);

  // rage aura
  if (p.rage >= 100) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 0.25 + Math.sin(time * 12) * 0.1;
    glow(ctx, 0, -26, 26, '#ff5a1e', 0.4, 4);
    ctx.restore();
  }
  if (p.hitFlash > 0) {
    ctx.globalCompositeOperation = 'source-atop';
    ctx.globalAlpha = Math.min(0.65, p.hitFlash * 2);
    ctx.fillStyle = '#ff3a1a';
    ctx.fillRect(-20, -56, 40, 60);
  }
  ctx.restore();
}

// ------------------------------------------------------------- legionnaire
export function drawLegionnaire(ctx, e, time) {
  ctx.save();
  ctx.translate(Math.round(e.x), Math.round(e.y));
  ctx.scale(e.facing, 1);
  if (e.hurtT > 0 && Math.floor(time * 40) % 2 === 0) ctx.globalAlpha = 0.65;
  if (e.spawnT > 0) ctx.globalAlpha = clamp(1 - e.spawnT / 0.45, 0.15, 1);

  const walk = Math.sin(e.walkPhase);
  const atk = e.state === 'windup' ? Math.min(1, e.stateT / 0.35) : e.state === 'strike' ? 1 : 0;
  const dead = e.state === 'dying';
  const lean = dead ? 0 : e.state === 'strike' ? 3 : 0;

  // legs
  const lx = dead ? -8 : walk * 2.5;
  const rx = dead ? 4 : -walk * 2.5;
  limb(ctx, -3, -14, -4 + lx, 0, '#8d8072', 3, '#211a1b');
  limb(ctx, 3, -14, 4 + rx, 0, '#a4947e', 3, '#211a1b');
  px(ctx, -6 + lx, -1, 5, 2, '#3a3233');
  px(ctx, 2 + rx, -1, 5, 2, '#3a3233');

  // tattered skirt
  for (let i = -3; i <= 3; i++) {
    px(ctx, i * 2 - 1, -18, 2, 5 + ((i * 5) % 3), i % 2 ? '#6d1210' : '#4a1a16');
  }
  // ribcage
  px(ctx, -6 + lean, -28, 12, 11, '#3a3233');
  px(ctx, -5 + lean, -27, 10, 9, '#b9a99a');
  for (let i = 0; i < 3; i++) px(ctx, -5 + lean, -26 + i * 3, 9, 1, '#5c4a3f');
  px(ctx, -1 + lean, -25, 1, 7, '#2a2020');
  // breastplate fragment
  px(ctx, -7 + lean, -29, 4, 7, '#2c2320');
  px(ctx, -7 + lean, -29, 4, 1, '#6b4a2e');

  // arms + sword
  const sh = { x: 5 + lean, y: -28 };
  let hand = { x: 9, y: -18 };
  let ang = 2.2;
  if (atk > 0) {
    if (e.state === 'windup') {
      hand = { x: 6, y: -36 - atk * 3 };
      ang = -1.2;
    } else {
      hand = { x: 12, y: -22 };
      ang = 0.15;
    }
  }
  limb(ctx, sh.x, sh.y, hand.x, hand.y, '#b9a99a', 3, '#211a1b');
  px(ctx, hand.x - 2, hand.y - 2, 4, 4, '#3a2a1e');
  // rusty sword
  const tx2 = hand.x + Math.cos(ang) * 17;
  const ty2 = hand.y + Math.sin(ang) * 17;
  line(ctx, hand.x, hand.y, tx2, ty2, '#575e66', 2);
  line(ctx, hand.x, hand.y, tx2, ty2, '#8d8072', 1);
  px(ctx, tx2, ty2, 2, 2, '#cbb694');
  // shield on the back arm
  px(ctx, -11 + lean, -27, 6, 10, '#2c2320');
  px(ctx, -11 + lean, -27, 6, 1, '#6b4a2e');
  px(ctx, -9 + lean, -24, 2, 2, '#6d1210');

  // skull head with helm
  const hx = lean;
  px(ctx, hx - 3, -39, 7, 7, '#cbb694');
  px(ctx, hx - 3, -39, 2, 7, '#dcc7a2');
  px(ctx, hx + 1, -36, 2, 2, '#2a2020');
  px(ctx, hx + 2, -35, 1, 1, '#e04b2a');
  px(ctx, hx + 3, -36, 1, 1, '#e04b2a');
  px(ctx, hx - 2, -36, 2, 1, '#2a2020');
  px(ctx, hx - 3, -33, 7, 2, '#8d8072');
  // helmet
  px(ctx, hx - 4, -42, 8, 4, '#463d3d');
  px(ctx, hx - 4, -42, 8, 1, '#6b4a2e');
  px(ctx, hx - 5, -40, 2, 3, '#6b4a2e');
  px(ctx, hx + 3, -40, 2, 3, '#6b4a2e');
  px(ctx, hx - 1, -43, 1, 5, '#2a2020');
  // horns
  px(ctx, hx - 6, -41, 2, 2, '#cbb694');
  px(ctx, hx + 5, -41, 2, 2, '#cbb694');
  px(ctx, hx - 7, -39, 2, 1, '#a4947e');
  px(ctx, hx + 6, -39, 2, 1, '#a4947e');

  // death fade handled by caller
  ctx.restore();
}

// ----------------------------------------------------------------- harpy
export function drawHarpy(ctx, e, time) {
  ctx.save();
  ctx.translate(Math.round(e.x), Math.round(e.y));
  ctx.scale(e.facing, 1);
  if (e.hurtT > 0 && Math.floor(time * 40) % 2 === 0) ctx.globalAlpha = 0.65;
  if (e.spawnT > 0) ctx.globalAlpha = clamp(1 - e.spawnT / 0.45, 0.15, 1);

  const flap = Math.sin(time * 9 + e.seed) * 5;
  const dive = e.state === 'dive';
  const lean = dive ? 6 : 0;

  // wings (dark ragged)
  ctx.fillStyle = '#241a1e';
  fillPoly(ctx, [-2, -6, -26, -14 - flap, -20, -2 - flap, -4, 2], '#241a1e');
  fillPoly(ctx, [-4, -8, -22, -13 - flap, -17, -5 - flap, -5, -3], '#3a2a33');
  fillPoly(ctx, [2, -8, 20, -16 + flap, 16, -4 + flap, 4, 0], '#2c2026');
  fillPoly(ctx, [3, -9, 17, -14 + flap, 14, -6 + flap, 4, -2], '#463a42');
  // wing bones
  line(ctx, -3, -7, -20, -11 - flap, '#5c4a3f', 1);
  line(ctx, 3, -8, 16, -14 + flap, '#5c4a3f', 1);

  // body
  px(ctx, -4 + lean, -12, 8, 10, '#5c4a3f');
  px(ctx, -3 + lean, -12, 5, 9, '#8d8072');
  px(ctx, -3 + lean, -10, 3, 6, '#c9b39e');
  // tatters
  for (let i = 0; i < 4; i++) px(ctx, -3 + lean + i * 2, -3, 1, 2 + (i % 2), '#4a1a16');
  // head
  px(ctx, -2 + lean, -18, 6, 6, '#c9b39e');
  px(ctx, 1 + lean, -17, 2, 1, '#e04b2a');
  px(ctx, 0 + lean, -16, 1, 1, '#e04b2a');
  px(ctx, -3 + lean, -19, 5, 2, '#241a1e');
  px(ctx, -4 + lean, -18, 2, 3, '#241a1e');
  // talons
  const cl = dive ? 4 : 0;
  line(ctx, -2, -2, -5 - cl, 4 + cl, '#cbb694', 1);
  line(ctx, 2, -2, 5 + cl, 4 + cl, '#cbb694', 1);
  line(ctx, -5 - cl, 4 + cl, -7, 6 + cl, '#8d8072', 1);
  line(ctx, 5 + cl, 4 + cl, 7, 6 + cl, '#8d8072', 1);
  ctx.restore();
}

// --------------------------------------------------------------- minotaur
export function drawMinotaur(ctx, e, time) {
  ctx.save();
  ctx.translate(Math.round(e.x), Math.round(e.y));
  ctx.scale(e.facing, 1);
  if (e.hurtT > 0 && Math.floor(time * 40) % 2 === 0) ctx.globalAlpha = 0.7;
  if (e.spawnT > 0) ctx.globalAlpha = clamp(1 - e.spawnT / 0.6, 0.1, 1);

  const dead = e.state === 'dying';
  const walk = Math.sin(e.walkPhase);
  const charging = e.state === 'charge';
  const windup = e.state === 'windup';
  const slam = e.state === 'slam';
  const lean = dead ? 0 : charging ? 6 : windup ? -3 : 0;
  const crouch = slam ? 4 : 0;

  // legs
  const lx = dead ? -10 : walk * 5;
  const rx = dead ? 8 : -walk * 5;
  limb(ctx, -7, -20, -9 + lx, 0, '#6b3a35', 6, '#1a0f10');
  limb(ctx, 7, -20, 9 + rx, 0, '#7d4440', 6, '#1a0f10');
  px(ctx, -13 + lx, -2, 9, 3, '#241a1e');
  px(ctx, 4 + rx, -2, 9, 3, '#241a1e');
  // hooves
  px(ctx, -14 + lx, -4, 3, 3, '#cbb694');
  px(ctx, 5 + rx, -4, 3, 3, '#cbb694');

  // loincloth / belt
  px(ctx, -13, -26 - crouch, 26, 7, '#3a2a1e');
  px(ctx, -13, -26 - crouch, 26, 1, '#6b4a2e');
  for (let i = -5; i <= 5; i += 2) px(ctx, i * 2, -20 - crouch, 3, 6, i % 3 ? '#4a1a16' : '#6d1210');
  px(ctx, 2, -24 - crouch, 6, 4, '#b8894a');

  // torso
  px(ctx, -14 + lean, -44 - crouch, 28, 20, '#6b3a35');
  px(ctx, -14 + lean, -44 - crouch, 8, 20, '#8a4a42');
  px(ctx, 8 + lean, -44 - crouch, 6, 20, '#4d2825');
  // muscle shading
  px(ctx, -6 + lean, -40 - crouch, 12, 2, '#4d2825');
  px(ctx, -2 + lean, -36 - crouch, 4, 8, '#4d2825');
  px(ctx, -10 + lean, -32 - crouch, 6, 3, '#8a4a42');
  // war paint
  px(ctx, -9 + lean, -42 - crouch, 3, 10, '#c43622');
  px(ctx, 5 + lean, -38 - crouch, 6, 2, '#c43622');
  // chest strap
  fillPoly(ctx, [-12 + lean, -30 - crouch, -2 + lean, -44 - crouch, 6 + lean, -44 - crouch, 12 + lean, -36 - crouch, 12 + lean, -33 - crouch, 4 + lean, -41 - crouch, -8 + lean, -28 - crouch], '#2c2320');

  // arms
  const shY = -42 - crouch;
  let handL = { x: -18, y: -24 - crouch };
  let handR = { x: 18, y: -24 - crouch };
  let axeAng = 0.9;
  if (windup) {
    const w = Math.min(1, e.stateT / 0.5);
    handR = { x: 14, y: -52 - w * 6 };
    axeAng = -1.6;
    handL = { x: -18, y: -34 };
  } else if (slam) {
    const w = Math.min(1, e.stateT / 0.2);
    handR = { x: 16 + w * 6, y: -30 + w * 16 };
    axeAng = 1.2;
    handL = { x: -16, y: -22 };
  } else if (charging) {
    handR = { x: 22, y: -30 };
    axeAng = 0.4;
    handL = { x: -22, y: -30 };
  }
  // back arm
  limb(ctx, -12 + lean, shY, handL.x, handL.y, '#6b3a35', 5, '#1a0f10');
  // front arm
  limb(ctx, 12 + lean, shY, handR.x, handR.y, '#8a4a42', 6, '#1a0f10');
  px(ctx, handR.x - 2, handR.y - 2, 5, 5, '#2c2320');
  px(ctx, handL.x - 2, handL.y - 2, 5, 5, '#2c2320');

  // giant axe
  const ax = handR.x + Math.cos(axeAng) * 20;
  const ay = handR.y + Math.sin(axeAng) * 20;
  line(ctx, handR.x, handR.y, ax, ay, '#3a2a1e', 3);
  line(ctx, handR.x, handR.y, ax, ay, '#6b4a2e', 1);
  const nx = -Math.sin(axeAng);
  const ny = Math.cos(axeAng);
  fillPoly(ctx, [ax - nx * 9, ay - ny * 9, ax + nx * 9, ay + ny * 9, ax + nx * 9 + Math.cos(axeAng) * 8, ay + ny * 9 + Math.sin(axeAng) * 8, ax - nx * 9 + Math.cos(axeAng) * 6, ay - ny * 9 + Math.sin(axeAng) * 6], '#575e66');
  fillPoly(ctx, [ax - nx * 7, ay - ny * 7, ax + nx * 7, ay + ny * 7, ax + nx * 7 + Math.cos(axeAng) * 5, ay + ny * 7 + Math.sin(axeAng) * 5, ax - nx * 7 + Math.cos(axeAng) * 4, ay - ny * 7 + Math.sin(axeAng) * 4], '#8d8072');
  px(ctx, ax - nx * 8, ay - ny * 8, 2, 2, '#cbb694');
  px(ctx, ax + Math.cos(axeAng) * 6, ay + Math.sin(axeAng) * 6, 2, 2, '#5a1c18');

  // bull head
  const hy = -58 - crouch + (windup ? 1 : 0);
  px(ctx, -8 + lean, hy, 16, 14, '#5c3230');
  px(ctx, -8 + lean, hy, 5, 14, '#7d4440');
  px(ctx, 5 + lean, hy + 2, 4, 11, '#3d2020');
  // muzzle
  px(ctx, -1 + lean, hy + 8, 9, 7, '#8a5a4f');
  px(ctx, -1 + lean, hy + 8, 9, 2, '#a8756a');
  px(ctx, 5 + lean, hy + 10, 3, 3, '#3d1a18');
  px(ctx, 1 + lean, hy + 12, 5, 1, '#3d1a18');
  // nose ring
  ring(ctx, 4 + lean, hy + 12, 2, '#d9ac63');
  // eyes
  px(ctx, -5 + lean, hy + 4, 4, 2, '#2a0d0c');
  px(ctx, -4 + lean, hy + 4, 2, 2, '#ff6a32');
  px(ctx, 1 + lean, hy + 3, 4, 2, '#2a0d0c');
  px(ctx, 2 + lean, hy + 3, 2, 2, '#ff6a32');
  // horns
  fillPoly(ctx, [-8 + lean, hy + 2, -18 + lean, hy - 6, -16 + lean, hy - 9, -5 + lean, hy + 1], '#dcc7a2');
  fillPoly(ctx, [8 + lean, hy + 2, 18 + lean, hy - 6, 16 + lean, hy - 9, 5 + lean, hy + 1], '#cbb694');
  px(ctx, -15 + lean, hy - 6, 2, 2, '#f7e6c2');
  px(ctx, 15 + lean, hy - 6, 2, 2, '#f7e6c2');
  // ears
  px(ctx, -12 + lean, hy + 5, 4, 2, '#3d2020');
  px(ctx, 8 + lean, hy + 5, 4, 2, '#3d2020');

  if (windup) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 0.4;
    glow(ctx, 0, hy + 4, 22, '#ff4a1e', 0.4, 4);
    ctx.restore();
  }
  if (e.hitFlash > 0) {
    ctx.globalCompositeOperation = 'source-atop';
    ctx.globalAlpha = Math.min(0.7, e.hitFlash * 2);
    ctx.fillStyle = '#ff3a1a';
    ctx.fillRect(-30, -80, 60, 84);
  }
  ctx.restore();
}

// Arena combat: waves of undead, harpies, and the Minotaur boss.
import { drawText, drawLogo, px, disc, ring, glow, clamp, lerp, measureText, W, H, makeCanvas, mulberry32 } from './pixel.js';
import { input } from './input.js';
import { Save } from './save.js';
import { audio } from './audio.js';
import {
  GROUND_Y, buildArenaBackdrop, drawKratos, drawLegionnaire, drawHarpy,
  drawMinotaur, line,
} from './battleArt.js';

const LEFT_BOUND = 34;
const RIGHT_BOUND = 446;
const GOLD = '#d9ab5c';
const GOLD_DIM = '#8a6534';
const CREAM = '#efe3cf';
const ASH = '#b9a99a';
const RED = '#a3221b';
const RED_DARK = '#6d1210';

const WAVES = [
  {
    title: 'THE ASHES RISE',
    sub: 'WAVE I',
    spawns: ['legionnaire', 'legionnaire', 'legionnaire'],
  },
  {
    title: 'HOUNDS OF HADES',
    sub: 'WAVE II',
    spawns: ['legionnaire', 'harpy', 'legionnaire', 'harpy', 'legionnaire'],
  },
  {
    title: 'THE FALLEN LEGION',
    sub: 'WAVE III',
    spawns: ['legionnaire', 'legionnaire', 'harpy', 'legionnaire', 'harpy', 'legionnaire', 'legionnaire'],
  },
  {
    title: 'WRATH OF ARES',
    sub: 'WAVE IV',
    spawns: ['harpy', 'legionnaire', 'legionnaire', 'harpy', 'legionnaire', 'legionnaire', 'harpy', 'legionnaire'],
  },
  {
    title: 'THE MINOTAUR',
    sub: 'WAVE V',
    boss: true,
    spawns: ['minotaur', 'legionnaire', 'harpy', 'legionnaire', 'harpy'],
  },
];

const ENEMY_INFO = {
  legionnaire: { hp: 42, speed: 34, score: 90, radius: 28 },
  harpy: { hp: 28, speed: 42, score: 130, radius: 26 },
  minotaur: { hp: 340, speed: 26, score: 1400, radius: 46 },
};

function waveOf(n) {
  return WAVES[clamp(n - 1, 0, WAVES.length - 1)];
}

export class GameScene {
  constructor(app, opts = {}) {
    this.app = app;
    this.backdrop = app.arenaBackdrop;
    this.time = 0;
    this.hitstop = 0;
    this.shake = 0;
    this.flash = 0;
    this.lightningIn = 8;
    this.lightning = 0;
    this.paused = false;
    this.pauseIndex = 0;
    this.status = 'playing';
    this.statusT = 0;
    this.overlayIndex = 0;
    this.statusRecorded = false;
    this.hintT = 11;
    this.arenaDecals = [];
    this.particles = [];
    this.orbs = [];
    this.texts = [];
    this.waves = [];
    this.pendingVictory = 0;

    const run = opts.resume ? Save.progress.run : null;
    this.player = {
      x: 122,
      y: GROUND_Y,
      vy: 0,
      onGround: true,
      facing: 1,
      hp: run ? clamp(run.hp, 30, 100) : 100,
      maxHp: 100,
      rage: run ? clamp(run.rage || 0, 0, 100) : 0,
      state: 'idle',
      stateT: 0,
      walkPhase: 0,
      invuln: 0,
      dashT: 0,
      dashCd: 0,
      dashDir: 1,
      attackStep: 0,
      attackT: 0,
      attackDur: 0.24,
      attackHasHit: false,
      attackBuffer: 0,
      comboWindow: 0,
      hitFlash: 0,
      deadT: 0,
    };

    this.score = run ? run.score : 0;
    this.kills = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.bestCombo = 0;
    this.finished = false;
    this.damageTakenThisWave = false;
    this.ash = Array.from({ length: 46 }, () => ({
      x: Math.random() * W,
      y: Math.random() * H,
      vy: 6 + Math.random() * 14,
      vx: -8 + Math.random() * 16,
      a: 0.15 + Math.random() * 0.35,
      s: Math.random() < 0.85 ? 1 : 2,
    }));

    const startWave = run ? clamp(run.wave, 1, 5) : 1;
    this.setupWave(startWave, true);
    audio.setMode('battle');
  }

  // ------------------------------------------------------------- wave logic
  setupWave(number, initial = false) {
    this.wave = number;
    const data = waveOf(number);
    this.spawnQueue = [...data.spawns];
    this.spawnTimer = 1.1;
    this.waveState = 'banner';
    this.waveTimer = initial ? 2.8 : 2.4;
    this.waveTitle = data.title;
    this.waveSub = data.sub;
    this.bannerT = this.waveTimer;
    this.bossSpawned = false;
    this.damageTakenThisWave = false;
    this.clearedBonus = 0;
    Save.checkpoint({
      wave: number,
      score: Math.floor(this.score),
      hp: Math.round(this.player.hp),
      rage: Math.round(this.player.rage),
    });
  }

  spawnEnemy(type) {
    const info = ENEMY_INFO[type];
    const fromLeft = Math.random() < 0.5;
    let x = fromLeft ? -22 : W + 22;
    let y = GROUND_Y;
    if (type === 'harpy') {
      x = fromLeft ? 40 : W - 40;
      y = 120 + Math.random() * 40;
    } else if (type === 'minotaur') {
      x = fromLeft ? 70 : W - 70;
    }
    const e = {
      type,
      x,
      y,
      vy: 0,
      hp: info.hp,
      maxHp: info.hp,
      speed: info.speed,
      facing: x < this.player.x ? 1 : -1,
      state: 'walk',
      stateT: 0,
      walkPhase: Math.random() * 6,
      seed: Math.random() * 6,
      attackCd: 0.9 + Math.random() * 0.8,
      hurtT: 0,
      hitFlash: 0,
      kb: 0,
      spawnT: 0.55,
      baseY: y,
      diveCd: 1.4 + Math.random(),
      deathT: 0,
      contactCd: 0,
      chargeDir: 0,
      chargeT: 0,
    };
    if (type === 'minotaur') {
      e.spawnT = 0.8;
      this.boss = e;
      this.bossSpawned = true;
      this.shake = Math.max(this.shake, 6);
    }
    this.enemies.push(e);
    this.enemies.sort((a, b) => a.y - b.y);
    this.shake = Math.max(this.shake, type === 'minotaur' ? 8 : 3);
    this.spawnSmoke(x, GROUND_Y - 4, type === 'minotaur' ? 26 : 10, true);
  }

  // --------------------------------------------------------------- particles
  addParticle(p) {
    if (this.particles.length > 340) this.particles.shift();
    this.particles.push(p);
  }

  spawnBlood(x, y, count = 8, dir = 0, power = 1) {
    if (!Save.settings.blood) return;
    for (let i = 0; i < count; i++) {
      const a = dir + (Math.random() - 0.5) * 2.4;
      const sp = (20 + Math.random() * 90) * power;
      this.addParticle({
        type: 'blood',
        x, y,
        vx: Math.cos(a) * sp + dir * 30,
        vy: Math.sin(a) * sp - 40 * Math.random() * power,
        g: 420,
        life: 0.35 + Math.random() * 0.5,
        max: 0.85,
        size: Math.random() < 0.75 ? 1 : 2,
        color: Math.random() < 0.6 ? '#a3221b' : Math.random() < 0.5 ? '#6d1210' : '#c43622',
      });
    }
    this.addDecal(x + (Math.random() - 0.5) * 14, GROUND_Y + 3 + Math.random() * 18, 4 + Math.random() * 6);
  }

  spawnSpark(x, y, count = 6, dir = 0) {
    for (let i = 0; i < count; i++) {
      const a = dir + (Math.random() - 0.5) * 2.2;
      const sp = 40 + Math.random() * 120;
      this.addParticle({
        type: 'spark',
        x, y,
        vx: Math.cos(a) * sp,
        vy: Math.sin(a) * sp - 30,
        g: 320,
        life: 0.15 + Math.random() * 0.3,
        max: 0.45,
        size: 1,
        color: Math.random() < 0.5 ? '#ffd27a' : '#ff9d3a',
      });
    }
  }

  spawnFlame(x, y, count = 2, dir = 1) {
    for (let i = 0; i < count; i++) {
      this.addParticle({
        type: 'flame',
        x: x + (Math.random() - 0.5) * 8,
        y: y + (Math.random() - 0.5) * 8,
        vx: dir * (10 + Math.random() * 30) + (Math.random() - 0.5) * 20,
        vy: -10 - Math.random() * 30,
        g: -30,
        life: 0.14 + Math.random() * 0.24,
        max: 0.38,
        size: Math.random() < 0.6 ? 1 : 2,
        color: Math.random() < 0.4 ? '#ffe6a0' : Math.random() < 0.6 ? '#ffab3c' : '#e0622a',
      });
    }
  }

  spawnSmoke(x, y, count = 6, big = false) {
    for (let i = 0; i < count; i++) {
      this.addParticle({
        type: 'smoke',
        x: x + (Math.random() - 0.5) * (big ? 50 : 16),
        y: y - Math.random() * (big ? 20 : 6),
        vx: (Math.random() - 0.5) * 26,
        vy: -12 - Math.random() * 24,
        g: -6,
        life: 0.6 + Math.random() * 0.8,
        max: 1.4,
        size: big ? 3 + Math.random() * 4 : 2 + Math.random() * 3,
        color: Math.random() < 0.5 ? '#3a3233' : '#544948',
        soft: true,
      });
    }
  }

  addDecal(x, y, r) {
    this.arenaDecals.push({ x, y, r, seed: Math.random() * 100 });
    if (this.arenaDecals.length > 36) this.arenaDecals.shift();
  }

  addText(text, x, y, color = CREAM, size = 1) {
    this.texts.push({ text: String(text), x, y, color, size, life: 0.9, vy: -26 });
  }

  // --------------------------------------------------------------- combat
  startAttack(step = 0) {
    const p = this.player;
    p.state = 'attack';
    p.attackStep = step;
    p.attackT = 0;
    p.attackDur = step === 2 ? 0.34 : 0.24;
    p.attackHasHit = false;
    p.attackBuffer = 0;
    p.comboWindow = 0.5;
    p.stateT = 0;
    if (step === 0) p.vxLunge = 40;
    audio.sfx('swing');
  }

  startHeavy() {
    const p = this.player;
    p.state = 'heavy';
    p.attackT = 0;
    p.attackDur = 0.52;
    p.attackHasHit = false;
    p.stateT = 0;
    p.comboWindow = 0;
    audio.sfx('swing');
  }

  attackHit(step) {
    const p = this.player;
    const heavy = step === 3;
    const range = heavy ? 52 : step === 2 ? 44 : 38;
    const dmg = heavy ? 30 : step === 2 ? 20 : 12;
    const cy = p.y - 22;
    let hitAny = false;
    for (const e of this.enemies) {
      if (e.hp <= 0 || e.spawnT > 0.2) continue;
      const ex = e.x;
      const ey = e.type === 'harpy' ? e.y : e.y - 16;
      const dx = (ex - p.x) * p.facing;
      if (dx < -6 || dx > range) continue;
      if (Math.abs(ey - cy) > (heavy ? 40 : 32)) continue;
      this.damageEnemy(e, dmg * (1 + Math.min(this.combo, 12) * 0.03), p.facing);
      hitAny = true;
    }
    if (hitAny) {
      this.hitstop = heavy ? 0.075 : 0.045;
      this.shake = Math.max(this.shake, heavy ? 7 : 3.4);
      this.spawnFlame(p.x + p.facing * 24, p.y - 26, 8, p.facing);
    } else {
      this.spawnFlame(p.x + p.facing * 22, p.y - 28, 3, p.facing);
    }
  }

  damageEnemy(e, dmg, dir) {
    if (e.hp <= 0) return;
    e.hp -= dmg;
    e.hurtT = 0.16;
    e.hitFlash = 0.18;
    e.kb = dir * (e.type === 'minotaur' ? 18 : 78);
    this.combo += 1;
    this.comboTimer = 2.6;
    this.bestCombo = Math.max(this.bestCombo, this.combo);
    this.score += Math.round(dmg * 1.6) + Math.min(this.combo, 20) * 2;
    this.player.rage = Math.min(100, this.player.rage + 3.5);
    const sx = e.type === 'harpy' ? e.x : e.x;
    const sy = e.type === 'harpy' ? e.y : e.y - 18;
    this.spawnBlood(sx, sy, 7, dir > 0 ? 0 : Math.PI, 0.9);
    this.spawnSpark(sx, sy, 5, dir > 0 ? 0 : Math.PI);
    audio.sfx('hit');
    if (e.type !== 'minotaur') {
      e.state = 'hurt';
      e.stateT = 0.22;
    } else if (e.hp > 0) {
      this.addText(Math.round(dmg), e.x, e.y - 62, '#ffd27a', 1);
    }
    if (e.hp <= 0) this.killEnemy(e);
  }

  killEnemy(e) {
    e.state = 'dying';
    e.deathT = e.type === 'minotaur' ? 1.6 : 0.55;
    e.hp = 0;
    const info = ENEMY_INFO[e.type];
    this.kills += 1;
    this.score += info.score + this.combo * 5;
    this.spawnBlood(e.x, e.type === 'harpy' ? e.y : e.y - 16, 18, 0, 1.3);
    this.spawnSmoke(e.x, e.y - 10, e.type === 'minotaur' ? 14 : 5, e.type === 'minotaur');
    this.addDecal(e.x, GROUND_Y + 6 + Math.random() * 14, e.type === 'minotaur' ? 18 : 8);
    audio.sfx('enemyDie');
    this.shake = Math.max(this.shake, e.type === 'minotaur' ? 12 : 4);
    this.addText(`+${info.score}`, e.x, e.y - 40, '#ffd27a', 1);
    const orbCount = e.type === 'minotaur' ? 12 : 4;
    for (let i = 0; i < orbCount; i++) {
      this.orbs.push({
        x: e.x,
        y: (e.type === 'harpy' ? e.y : e.y - 14) - 4,
        vx: (Math.random() - 0.5) * 90,
        vy: -40 - Math.random() * 90,
        delay: 0.35 + Math.random() * 0.25,
        type: 'score',
        life: 8,
      });
    }
    if (Math.random() < 0.22 || e.type === 'minotaur') {
      this.orbs.push({
        x: e.x,
        y: e.y - 20,
        vx: (Math.random() - 0.5) * 40,
        vy: -60,
        delay: 0.6,
        type: 'hp',
        life: 10,
      });
    }
    const totalKills = Save.progress.kills + this.kills;
    if (totalKills >= 1) Save.unlock('firstblood');
    if (totalKills >= 25) Save.unlock('centurion');
    if (e.type === 'minotaur') {
      Save.unlock('titan');
      this.boss = null;
      this.pendingVictory = 1.4;
      this.flash = 0.8;
    }
  }

  hurtPlayer(dmg, fromX) {
    const p = this.player;
    if (p.invuln > 0 || p.dashT > 0 || this.status !== 'playing') return;
    p.hp -= dmg;
    p.invuln = 0.95;
    p.hitFlash = 0.3;
    p.state = 'hurt';
    p.stateT = 0.3;
    p.vy = -140;
    p.onGround = false;
    if (fromX !== undefined) p.x += (p.x > fromX ? 1 : -1) * 8;
    this.combo = 0;
    this.comboTimer = 0;
    this.shake = 7;
    this.flash = 0.35;
    this.damageTakenThisWave = true;
    this.spawnBlood(p.x, p.y - 24, 14, 0, 1);
    audio.sfx('hurt');
    if (p.hp <= 0) {
      p.hp = 0;
      this.die();
    }
  }

  unleashRage() {
    const p = this.player;
    if (p.rage < 100) return;
    p.rage = 0;
    p.invuln = 1.0;
    this.hitstop = 0.1;
    this.shake = 14;
    this.flash = 0.7;
    audio.sfx('rage');
    p.hp = Math.min(p.maxHp, p.hp + 15);
    for (const e of this.enemies) {
      if (e.hp <= 0) continue;
      const d = Math.hypot(e.x - p.x, (e.y - 16) - (p.y - 20));
      if (d < 132) {
        this.damageEnemy(e, 95, e.x > p.x ? 1 : -1);
        e.kb = (e.x > p.x ? 1 : -1) * 160;
      }
    }
    for (let i = 0; i < 60; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = Math.random() * 120;
      this.spawnFlame(p.x + Math.cos(a) * r, p.y - 20 + Math.sin(a) * r * 0.6, 1, Math.cos(a));
    }
    this.spawnSmoke(p.x, p.y - 20, 18, true);
    this.addText('RAGE OF SPARTA', p.x, p.y - 74, '#ff9d3a', 2);
  }

  die() {
    const p = this.player;
    p.state = 'dead';
    p.deadT = 0;
    this.status = 'dead';
    this.statusT = 0;
    this.overlayIndex = 0;
    audio.sfx('death');
    audio.setMode('menu');
    this.shake = 9;
    if (!this.statusRecorded) {
      this.statusRecorded = true;
      Save.recordRun({
        score: this.score,
        wave: this.wave,
        kills: this.kills,
        cleared: false,
        died: true,
      });
      Save.checkpoint(null);
      Save.progress.maxWave = Math.max(Save.progress.maxWave || 0, this.wave);
      this.app.persistProgress();
    }
  }

  victory() {
    if (this.status === 'victory') return;
    this.status = 'victory';
    this.statusT = 0;
    this.overlayIndex = 0;
    audio.sfx('victory');
    audio.setMode('menu');
    this.score += 500 + this.player.hp * 5;
    if (!this.statusRecorded) {
      this.statusRecorded = true;
      Save.recordRun({
        score: this.score,
        wave: 5,
        kills: this.kills,
        cleared: true,
        died: false,
      });
      Save.checkpoint(null);
      Save.progress.maxWave = 5;
      Save.unlock('god');
      this.app.persistProgress();
    }
  }

  // ----------------------------------------------------------------- update
  update(dt) {
    this.time += dt;
    this.shake = Math.max(0, this.shake - dt * 26);
    this.flash = Math.max(0, this.flash - dt * 2.4);
    this.hintT = Math.max(0, this.hintT - dt);
    if (this.toastT > 0) this.toastT -= dt;

    // lightning ambience
    this.lightningIn -= dt;
    if (this.lightningIn <= 0) {
      this.lightningIn = 9 + Math.random() * 12;
      this.lightning = 0.5;
      audio.sfx('thunder');
    }
    this.lightning = Math.max(0, this.lightning - dt * 2.2);

    this.updateAsh(dt);
    this.updateTexts(dt);

    // overlays first
    if (this.status === 'playing' && input.justPressed('pause')) {
      this.paused = !this.paused;
      this.pauseIndex = 0;
      audio.sfx(this.paused ? 'back' : 'select');
      if (this.paused) audio.setMode('menu');
      else audio.setMode('battle');
    }
    if (this.paused) {
      this.updatePause(dt);
      return;
    }
    if (this.status === 'dead') {
      this.statusT += dt;
      this.player.deadT += dt;
      this.updateParticles(dt);
      this.updateOverlay(dt, 2, true);
      return;
    }
    if (this.status === 'victory') {
      this.statusT += dt;
      this.updateParticles(dt);
      this.updateOrbs(dt);
      this.updateOverlay(dt, 2, false);
      return;
    }

    if (this.hitstop > 0) {
      this.hitstop -= dt;
      this.updateParticles(dt, true);
      return;
    }

    this.updatePlayer(dt);
    this.updateEnemies(dt);
    this.updateParticles(dt);
    this.updateOrbs(dt);
    this.updateWave(dt);

    if (this.comboTimer > 0) {
      this.comboTimer -= dt;
      if (this.comboTimer <= 0) this.combo = 0;
    }

    if (this.pendingVictory > 0) {
      this.pendingVictory -= dt;
      if (this.pendingVictory <= 0) this.victory();
    }

    // rage ready cue
    if (this.player.rage >= 100 && !this.rageCuePlayed) {
      this.rageCuePlayed = true;
      this.addText('RAGE READY — L', this.player.x, this.player.y - 72, '#ff9d3a', 1);
    }
    if (this.player.rage < 90) this.rageCuePlayed = false;
  }

  updateAsh(dt) {
    for (const a of this.ash) {
      a.y += a.vy * dt;
      a.x += a.vx * dt;
      if (a.y > H + 4) { a.y = -4; a.x = Math.random() * W; }
      if (a.x < -4) a.x = W + 4;
      if (a.x > W + 4) a.x = -4;
    }
  }

  updateTexts(dt) {
    for (const t of this.texts) {
      t.life -= dt;
      t.y += t.vy * dt;
      t.vy *= 0.94;
    }
    this.texts = this.texts.filter((t) => t.life > 0);
  }

  updatePlayer(dt) {
    const p = this.player;
    p.invuln = Math.max(0, p.invuln - dt);
    p.hitFlash = Math.max(0, p.hitFlash - dt);
    p.dashCd = Math.max(0, p.dashCd - dt);
    p.comboWindow = Math.max(0, p.comboWindow - dt);
    p.attackBuffer = Math.max(0, p.attackBuffer - dt);
    if (p.state === 'hurt') p.stateT -= dt;
    if (p.state === 'hurt' && p.stateT <= 0) p.state = 'idle';

    const moving = (input.isDown('left') ? -1 : 0) + (input.isDown('right') ? 1 : 0);

    // dash
    if (input.justPressed('dash') && p.dashCd <= 0 && p.state !== 'dead') {
      p.dashT = 0.2;
      p.dashCd = 0.55;
      p.dashDir = moving || p.facing;
      p.facing = p.dashDir;
      p.invuln = Math.max(p.invuln, 0.26);
      p.state = 'dash';
      this.spawnSmoke(p.x, p.y - 16, 5);
      audio.sfx('dash');
    }

    if (p.dashT > 0) {
      p.dashT -= dt;
      p.x += p.dashDir * 310 * dt;
      if (Math.random() < 0.5) this.spawnSmoke(p.x - p.dashDir * 10, p.y - 20, 1);
      if (p.dashT <= 0) p.state = 'idle';
    } else {
      // movement
      let speed = p.state === 'attack' || p.state === 'heavy' ? 18 : p.state === 'hurt' ? 22 : 118;
      if (p.state === 'dash') speed = 0;
      if (moving !== 0 && p.state !== 'hurt') {
        if (p.state !== 'attack' && p.state !== 'heavy') p.facing = moving;
        p.x += moving * speed * dt;
        p.walkPhase += dt * 10;
        if (p.onGround && p.state === 'idle') p.state = 'run';
      } else if (p.onGround && p.state === 'run') {
        p.state = 'idle';
      }
    }

    // jump
    if (input.justPressed('jump') && p.onGround && p.state !== 'hurt') {
      p.vy = -345;
      p.onGround = false;
      if (p.state === 'run') p.state = 'idle';
      audio.sfx('jump');
      this.spawnSmoke(p.x, p.y - 2, 3);
    }

    // attacks
    if (input.justPressed('attack')) {
      if (p.state === 'attack') {
        p.attackBuffer = 0.32;
      } else if (p.state === 'heavy' || p.state === 'hurt') {
        // ignore
      } else {
        this.startAttack(p.comboWindow > 0 ? Math.min(2, p.attackStep + 1) : 0);
      }
    }
    if (input.justPressed('heavy') && (p.state === 'idle' || p.state === 'run' || p.state === 'jump')) {
      this.startHeavy();
    }
    if (input.justPressed('rage')) this.unleashRage();

    // attack state progression
    if (p.state === 'attack') {
      p.attackT += dt;
      const dur = p.attackDur;
      if (!p.attackHasHit && p.attackT >= (p.attackStep === 2 ? 0.1 : 0.07)) {
        p.attackHasHit = true;
        this.attackHit(p.attackStep);
      }
      this.spawnFlame(p.x + p.facing * (24 + Math.random() * 9), p.y - 26 + (Math.random() - 0.5) * 12, 1, p.facing);
      if (p.attackT >= dur) {
        if (p.attackBuffer > 0 && p.attackStep < 2) {
          this.startAttack(p.attackStep + 1);
        } else {
          p.state = 'idle';
          p.comboWindow = 0.35;
          p.attackStep = 0;
          p.comboBuffer = 0;
        }
      }
    } else if (p.state === 'heavy') {
      p.attackT += dt;
      if (!p.attackHasHit && p.attackT >= 0.26) {
        p.attackHasHit = true;
        this.attackHit(3);
        this.shake = Math.max(this.shake, 6);
        audio.sfx('heavy');
        for (let i = 0; i < 10; i++) {
          this.spawnSmoke(p.x + (Math.random() - 0.5) * 60, GROUND_Y - 2, 1);
        }
        if (p.onGround) this.addDecal(p.x + p.facing * 30, GROUND_Y + 6, 6);
      }
      this.spawnFlame(p.x + p.facing * 26, p.y - 20, 1, p.facing);
      if (p.attackT >= p.attackDur) {
        p.state = 'idle';
        p.attackStep = 0;
      }
    }

    // physics
    p.vy += 980 * dt;
    p.y += p.vy * dt;
    p.x += (p.kb || 0) * dt;
    p.kb = (p.kb || 0) * 0.86;
    if (p.y >= GROUND_Y) {
      if (!p.onGround) {
        audio.sfx('land');
        this.spawnSmoke(p.x, GROUND_Y - 2, 4);
      }
      p.y = GROUND_Y;
      p.vy = 0;
      p.onGround = true;
    } else {
      p.onGround = false;
    }
    p.x = clamp(p.x, LEFT_BOUND, RIGHT_BOUND);

    // trail when dashing
    // (kept as particles above)
  }

  updateEnemies(dt) {
    const p = this.player;
    for (const e of this.enemies) {
      e.hurtT = Math.max(0, e.hurtT - dt);
      e.hitFlash = Math.max(0, e.hitFlash - dt);
      if (e.state === 'dying') {
        e.deathT -= dt;
        e.y = Math.min(GROUND_Y, e.y + 30 * dt);
        continue;
      }
      if (e.spawnT > 0) {
        e.spawnT -= dt;
        continue;
      }
      e.x += e.kb * dt;
      e.kb *= 0.85;
      e.x = clamp(e.x, -30, W + 30);
      e.facing = p.x < e.x ? -1 : 1;
      if (e.type === 'legionnaire') this.updateLegionnaire(e, dt);
      else if (e.type === 'harpy') this.updateHarpy(e, dt);
      else if (e.type === 'minotaur') this.updateMinotaur(e, dt);
    }
    this.enemies = this.enemies.filter((e) => !(e.state === 'dying' && e.deathT <= 0));
    this.enemies.sort((a, b) => a.y - b.y);
  }

  updateLegionnaire(e, dt) {
    const p = this.player;
    e.attackCd = Math.max(0, e.attackCd - dt);
    if (e.state === 'hurt') {
      e.stateT -= dt;
      if (e.stateT <= 0) e.state = 'walk';
      return;
    }
    if (e.state === 'windup') {
      e.stateT -= dt;
      if (e.stateT <= 0) {
        e.state = 'strike';
        e.stateT = 0.16;
        if (Math.abs(p.x - e.x) < 40 && Math.abs(p.y - e.y) < 26 && p.invuln <= 0) {
          this.hurtPlayer(9, e.x);
        }
        audio.sfx('swing');
      }
      return;
    }
    if (e.state === 'strike') {
      e.stateT -= dt;
      if (e.stateT <= 0) { e.state = 'walk'; e.attackCd = 1.25; }
      return;
    }
    const dx = p.x - e.x;
    const d = Math.abs(dx);
    if (d > 30) {
      e.x += e.facing * e.speed * dt;
      e.walkPhase += dt * 7;
    } else if (e.attackCd <= 0) {
      e.state = 'windup';
      e.stateT = 0.42;
    }
    // soft separation
    for (const o of this.enemies) {
      if (o === e || o.type !== 'legionnaire' || o.state === 'dying') continue;
      const sep = e.x - o.x;
      if (Math.abs(sep) < 18) e.x += Math.sign(sep || 1) * 12 * dt;
    }
  }

  updateHarpy(e, dt) {
    const p = this.player;
    e.attackCd = Math.max(0, e.attackCd - dt);
    if (e.state === 'hurt') {
      e.stateT -= dt;
      if (e.stateT <= 0) e.state = 'hover';
      return;
    }
    if (e.state === 'dive') {
      e.stateT -= dt;
      const t = 1 - Math.max(0, e.stateT) / 0.5;
      e.x = lerp(e.diveFrom.x, e.diveTo.x, t);
      e.y = lerp(e.diveFrom.y, e.diveTo.y, t);
      if (Math.hypot(p.x - e.x, (p.y - 18) - e.y) < 24 && p.invuln <= 0) {
        this.hurtPlayer(8, e.x);
        e.state = 'rise';
        e.stateT = 0.5;
      }
      if (e.stateT <= 0) {
        e.state = 'rise';
        e.stateT = 0.7;
      }
      return;
    }
    if (e.state === 'rise') {
      e.stateT -= dt;
      e.y = lerp(e.y, e.baseY, dt * 5);
      e.x += e.facing * e.speed * 0.7 * dt;
      if (e.stateT <= 0) {
        e.state = 'hover';
        e.attackCd = 1.5;
      }
      return;
    }
    // hover
    e.x += e.facing * e.speed * 0.45 * dt;
    e.x = clamp(e.x, 30, W - 30);
    e.y = e.baseY + Math.sin(this.time * 3 + e.seed) * 6;
    e.walkPhase += dt * 9;
    if (e.attackCd <= 0 && Math.abs(p.x - e.x) < 150) {
      e.state = 'dive';
      e.stateT = 0.5;
      e.diveFrom = { x: e.x, y: e.y };
      e.diveTo = { x: p.x + (p.x > e.x ? -12 : 12), y: p.y - 26 };
      audio.sfx('swing');
    }
  }

  updateMinotaur(e, dt) {
    const p = this.player;
    e.attackCd = Math.max(0, e.attackCd - dt);
    e.contactCd = Math.max(0, e.contactCd - dt);
    if (e.state === 'hurt') {
      e.stateT -= dt;
      if (e.stateT <= 0) e.state = 'walk';
      return;
    }
    if (e.state === 'windup') {
      e.stateT -= dt;
      if (e.stateT <= 0) {
        if (Math.random() < 0.55) {
          e.state = 'charge';
          e.stateT = 0.55;
          e.chargeDir = Math.sign(p.x - e.x) || 1;
          e.chargeT = 0;
          audio.sfx('rage');
        } else {
          e.state = 'slam';
          e.stateT = 0.9;
          e.slamDone = false;
          audio.sfx('heavy');
        }
      }
      return;
    }
    if (e.state === 'charge') {
      e.stateT -= dt;
      e.chargeT += dt;
      e.x += e.chargeDir * 215 * dt;
      e.walkPhase += dt * 16;
      if (Math.random() < 0.6) this.spawnSmoke(e.x - e.chargeDir * 12, GROUND_Y - 2, 1);
      if (Math.abs(p.x - e.x) < 34 && e.contactCd <= 0 && p.invuln <= 0) {
        this.hurtPlayer(17, e.x);
        e.contactCd = 1;
      }
      if (e.stateT <= 0 || e.x < 50 || e.x > W - 50) {
        e.state = 'recover';
        e.stateT = 0.6;
        this.shake = 5;
      }
      return;
    }
    if (e.state === 'slam') {
      e.stateT -= dt;
      const t = 0.9 - e.stateT;
      if (!e.slamDone && t > 0.45) {
        e.slamDone = true;
        this.shake = 11;
        audio.sfx('heavy');
        this.spawnSmoke(e.x, GROUND_Y - 2, 16, true);
        for (let i = 0; i < 12; i++) this.spawnSpark(e.x + (Math.random() - 0.5) * 70, GROUND_Y - 4, 1, 0);
        this.shockwaves.push(
          { x: e.x - 14, dir: -1, life: 1.35, hit: false },
          { x: e.x + 14, dir: 1, life: 1.35, hit: false },
        );
      }
      if (e.stateT <= 0) {
        e.state = 'recover';
        e.stateT = 0.7;
      }
      return;
    }
    if (e.state === 'recover') {
      e.stateT -= dt;
      if (e.stateT <= 0) { e.state = 'walk'; e.attackCd = 1.4; }
      return;
    }
    // walk
    const d = Math.abs(p.x - e.x);
    if (d > 52) {
      e.x += e.facing * e.speed * dt;
      e.walkPhase += dt * 6;
    }
    if (e.attackCd <= 0 && d < 130) {
      e.state = 'windup';
      e.stateT = 0.55;
    }
  }

  updateParticles(dt, frozen = false) {
    for (const p of this.particles) {
      p.life -= dt;
      if (frozen) continue;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += p.g * dt;
      if (p.type === 'blood' && p.y > GROUND_Y + 20) {
        p.life = 0;
      }
    }
    this.particles = this.particles.filter((p) => p.life > 0);
  }

  updateOrbs(dt) {
    const p = this.player;
    for (const o of this.orbs) {
      o.life -= dt;
      if (o.delay > 0) {
        o.delay -= dt;
        o.x += o.vx * dt;
        o.y += o.vy * dt;
        o.vy += 260 * dt;
        if (o.y > GROUND_Y + 8) { o.y = GROUND_Y + 8; o.vy *= -0.4; }
        continue;
      }
      const dx = p.x - o.x;
      const dy = (p.y - 22) - o.y;
      const d = Math.hypot(dx, dy) || 1;
      const sp = 300 + Math.min(260, (6 - o.life) * 60);
      o.x += (dx / d) * sp * dt;
      o.y += (dy / d) * sp * dt;
      if (d < 12) {
        o.life = 0;
        if (o.type === 'hp') {
          p.hp = Math.min(p.maxHp, p.hp + 8);
          audio.sfx('heal');
          this.addText('+8 HP', p.x, p.y - 52, '#9fe27a', 1);
        } else {
          this.score += 20;
          p.rage = Math.min(100, p.rage + 0.8);
          audio.sfx('orb');
        }
      }
    }
    this.orbs = this.orbs.filter((o) => o.life > 0);
    // shockwaves
    for (const s of this.shockwaves) {
      s.life -= dt;
      s.x += s.dir * 165 * dt;
      if (!s.hit && Math.abs(s.x - p.x) < 16 && p.y > GROUND_Y - 8) {
        s.hit = true;
        this.hurtPlayer(11, s.x);
      }
      if (Math.random() < 0.4) this.spawnSpark(s.x, GROUND_Y - 3, 1, 0);
    }
    this.shockwaves = this.shockwaves.filter((s) => s.life > 0);
  }

  updateWave(dt) {
    if (this.waveState === 'banner') {
      this.waveTimer -= dt;
      if (this.waveTimer <= 0) {
        this.waveState = 'fight';
        this.spawnTimer = 0.2;
      }
      return;
    }
    if (this.waveState === 'fight') {
      const alive = this.enemies.filter((e) => e.hp > 0).length;
      if (this.spawnQueue.length > 0) {
        this.spawnTimer -= dt;
        if (this.spawnTimer <= 0 && alive < 4) {
          const type = this.spawnQueue.shift();
          this.spawnEnemy(type);
          this.spawnTimer = 1.0 + Math.random() * 0.45;
        }
      } else if (alive === 0 && this.enemies.length === 0) {
        this.waveState = 'clear';
        this.waveTimer = 2.3;
        this.clearedBonus = 250 * this.wave;
        this.score += this.clearedBonus;
        this.player.hp = Math.min(this.player.maxHp, this.player.hp + 20);
        if (!this.damageTakenThisWave) Save.unlock('unbroken');
        audio.sfx('victory');
        if (this.wave < 5) {
          Save.checkpoint({
            wave: this.wave + 1,
            score: Math.floor(this.score),
            hp: Math.round(this.player.hp),
            rage: Math.round(this.player.rage),
          });
        }
        this.addText(`WAVE BONUS +${this.clearedBonus}`, this.player.x, this.player.y - 66, '#ffd27a', 1);
      }
      return;
    }
    if (this.waveState === 'clear') {
      this.waveTimer -= dt;
      if (this.waveTimer <= 0) {
        if (this.wave >= 5) {
          this.victory();
        } else {
          this.setupWave(this.wave + 1);
        }
      }
    }
  }

  updateOverlay(dt, count, dead) {
    if (this.statusT < 1.0) return;
    if (input.justPressed('up') || input.justPressed('down')) {
      this.overlayIndex = (this.overlayIndex + 1) % count;
      audio.sfx('move');
    }
    if (dead && this.statusT > 1.3) {
      if (input.justPressed('confirm')) this.selectOverlay(dead);
    } else if (!dead) {
      if (input.justPressed('confirm')) this.selectOverlay(dead);
    }
    const click = input.consumeClick();
    if (click) {
      for (let i = 0; i < count; i++) {
        const r = this.overlayButtonRect(i, count);
        if (click.x > r.x && click.x < r.x + r.w && click.y > r.y && click.y < r.y + r.h) {
          this.overlayIndex = i;
          this.selectOverlay(dead);
          break;
        }
      }
    }
  }

  selectOverlay(dead) {
    audio.sfx('select');
    if (this.overlayIndex === 0) {
      // retry / play again
      if (dead) this.app.startGame({ resume: true });
      else this.app.startGame({ resume: false });
    } else {
      this.app.toMenu();
    }
  }

  updatePause(dt) {
    if (input.justPressed('up') || input.justPressed('down')) {
      this.pauseIndex = (this.pauseIndex + 1) % 3;
      audio.sfx('move');
    }
    if (input.justPressed('back') || input.justPressed('pause')) {
      this.paused = false;
      audio.setMode('battle');
      audio.sfx('select');
      return;
    }
    if (input.justPressed('confirm')) {
      if (this.pauseIndex === 0) {
        this.paused = false;
        audio.setMode('battle');
        audio.sfx('select');
      } else if (this.pauseIndex === 1) {
        this.app.startGame({ resume: true });
      } else {
        this.app.toMenu();
      }
      return;
    }
    const click = input.consumeClick();
    if (click) {
      for (let i = 0; i < 3; i++) {
        const y = 135 + i * 24;
        if (click.x > 150 && click.x < 330 && click.y > y - 6 && click.y < y + 14) {
          this.pauseIndex = i;
          if (i === 0) { this.paused = false; audio.setMode('battle'); audio.sfx('select'); }
          else if (i === 1) this.app.startGame({ resume: true });
          else this.app.toMenu();
          break;
        }
      }
    }
  }

  // ----------------------------------------------------------------- render
  render(ctx) {
    const shakeOn = Save.settings.shake;
    const s = this.shake;
    const ox = shakeOn ? Math.round((Math.random() - 0.5) * s) : 0;
    const oy = shakeOn ? Math.round((Math.random() - 0.5) * s) : 0;

    ctx.save();
    ctx.translate(ox, oy);
    this.drawBackground(ctx);

    // decals
    for (const d of this.arenaDecals) {
      const rnd = mulberry32(Math.floor(d.seed * 1000));
      ctx.save();
      ctx.globalAlpha = 0.55;
      for (let i = 0; i < 4; i++) {
        ctx.fillStyle = i % 2 ? '#3d0d0c' : '#2a0808';
        ctx.beginPath();
        ctx.ellipse(d.x + (rnd() - 0.5) * d.r, d.y + (rnd() - 0.5) * 4, d.r * (0.3 + rnd() * 0.5), d.r * 0.18 + rnd(), 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }

    // shadows
    for (const e of this.enemies) {
      const fade = e.state === 'dying' ? clamp(e.deathT / 0.55, 0, 1) : 1;
      if (e.type === 'harpy') {
        ctx.save();
        ctx.globalAlpha = 0.2 * fade;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.ellipse(e.x, GROUND_Y + 3, 12, 3, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      } else {
        ctx.save();
        ctx.globalAlpha = 0.35 * fade;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.ellipse(e.x, GROUND_Y + 2, e.type === 'minotaur' ? 26 : 11, e.type === 'minotaur' ? 5 : 3, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
    }
    ctx.save();
    ctx.globalAlpha = 0.4;
    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.ellipse(this.player.x, GROUND_Y + 2, 13, 3.5, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // shockwaves (under enemies)
    for (const s2 of this.shockwaves) this.drawShockwave(ctx, s2);

    for (const e of this.enemies) {
      ctx.save();
      if (e.state === 'dying') {
        ctx.globalAlpha = clamp(e.deathT / 0.55, 0, 1);
        ctx.translate(0, (1 - ctx.globalAlpha) * 6);
      }
      if (e.type === 'legionnaire') drawLegionnaire(ctx, e, this.time);
      else if (e.type === 'harpy') drawHarpy(ctx, e, this.time);
      else drawMinotaur(ctx, e, this.time);
      if (e.hp > 0 && e.type !== 'minotaur') this.drawEnemyHealth(ctx, e);
      ctx.restore();
    }

    // player
    if (!(this.status === 'dead' && this.player.deadT > 0.8)) {
      drawKratos(ctx, this.player, this.time);
    }

    // particles
    this.drawParticles(ctx);

    // orbs
    for (const o of this.orbs) {
      const t = this.time * 6 + o.x;
      if (o.type === 'hp') {
        px(ctx, Math.round(o.x) - 2, Math.round(o.y) - 1, 5, 2, '#9fe27a');
        px(ctx, Math.round(o.x), Math.round(o.y) - 3, 1, 6, '#9fe27a');
        px(ctx, Math.round(o.x) - 1, Math.round(o.y), 3, 1, '#d9ffb0');
      } else {
        px(ctx, Math.round(o.x), Math.round(o.y), 2, 2, '#e04b2a');
        px(ctx, Math.round(o.x), Math.round(o.y), 1, 1, '#ffd27a');
        if (Math.sin(t) > 0.7) px(ctx, Math.round(o.x) - 1, Math.round(o.y) - 1, 3, 3, 'rgba(255,90,40,0.35)');
      }
    }

    // floating damage text
    for (const t of this.texts) {
      ctx.globalAlpha = clamp(t.life * 1.6, 0, 1);
      drawText(ctx, t.text, t.x, t.y, {
        scale: t.size, color: t.color, align: 'center', spacing: 1, outline: '#180606',
      });
    }
    ctx.globalAlpha = 1;

    this.drawForeground(ctx);
    ctx.restore();

    if (this.lightning > 0.02) {
      ctx.save();
      ctx.globalAlpha = Math.min(0.3, this.lightning * 0.6);
      ctx.fillStyle = '#dfe9ff';
      ctx.fillRect(0, 0, W, H);
      ctx.restore();
    }
    if (this.flash > 0.02) {
      ctx.save();
      ctx.globalAlpha = Math.min(0.38, this.flash * 0.5);
      ctx.fillStyle = '#ff6a32';
      ctx.fillRect(0, 0, W, H);
      ctx.restore();
    }

    this.drawHUD(ctx);

    if (this.paused) this.drawPause(ctx);
    if (this.status === 'dead' && this.statusT > 1.1) this.drawDead(ctx);
    if (this.status === 'victory' && this.statusT > 0.8) this.drawVictory(ctx);
  }

  drawBackground(ctx) {
    ctx.drawImage(this.backdrop, 0, 0);

    // statue eyes glow
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 0.35 + Math.sin(this.time * 2.3) * 0.15;
    glow(ctx, 230, 148, 7, '#ff5a1e', 0.5, 3);
    glow(ctx, 244, 148, 6, '#ff5a1e', 0.5, 3);
    ctx.restore();

    // lightning streaks in the upper sky
    if (this.lightning > 0.05) {
      const rnd = mulberry32(Math.floor(this.lightningIn * 100));
      ctx.save();
      ctx.globalAlpha = this.lightning;
      let x = 140 + rnd() * 200;
      let y = 0;
      ctx.fillStyle = '#eef5ff';
      while (y < 110) {
        const nx = x + (rnd() - 0.5) * 22;
        const ny = y + 8 + rnd() * 10;
        line(ctx, x, y, nx, ny, '#eef5ff', 1);
        x = nx;
        y = ny;
      }
      ctx.restore();
    }

    // drifting low fog
    for (let i = 0; i < 4; i++) {
      const off = (this.time * (6 + i * 2) + i * 160) % (W + 260) - 130;
      ctx.save();
      ctx.globalAlpha = 0.05 + i * 0.012;
      ctx.fillStyle = '#b9a99a';
      ctx.beginPath();
      ctx.ellipse(off, 208 + i * 6, 120, 8, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(off - 300, 214 + i * 5, 100, 7, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // ambient ash
    for (const a of this.ash) {
      ctx.globalAlpha = a.a;
      ctx.fillStyle = '#b9a99a';
      ctx.fillRect(a.x | 0, a.y | 0, a.s, a.s);
    }
    ctx.globalAlpha = 1;
  }

  drawForeground(ctx) {
    // fog over feet
    ctx.save();
    ctx.globalAlpha = 0.12;
    ctx.fillStyle = '#0c0909';
    ctx.beginPath();
    ctx.ellipse(240, 262, 280, 14, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    // subtle vignette
    ctx.save();
    const g = ctx.createRadialGradient(240, 135, 90, 240, 135, 280);
    g.addColorStop(0, 'rgba(0,0,0,0)');
    g.addColorStop(1, 'rgba(0,0,0,0.42)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
  }

  drawParticles(ctx) {
    for (const p of this.particles) {
      if (p.type === 'smoke') {
        ctx.globalAlpha = clamp(p.life / p.max, 0, 1) * 0.4;
        ctx.fillStyle = p.color;
        ctx.fillRect(Math.round(p.x - p.size / 2), Math.round(p.y - p.size / 2), p.size, p.size);
        continue;
      }
      ctx.globalAlpha = clamp(p.life / p.max, 0, 1);
      ctx.fillStyle = p.color;
