  }

  drawVictory(ctx) {
    ctx.save();
    ctx.fillStyle = 'rgba(6,3,2,0.6)';
    ctx.fillRect(0, 0, W, H);
    ctx.globalAlpha = clamp((this.statusT - 0.8) / 0.5, 0, 1);
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
