    glow(ctx, 240, 64, 90, '#ffb24a', 0.5, 5);
    ctx.restore();
    drawLogo(ctx, 'GOD OF WAR', 240 - (10 * 8 + 2 * 8 + 2 * 2 * 4) / 2, 32, 2, [
      '#5a3a12', '#8a6430', '#c7a052', '#f0d38a', '#ffeab0', '#fff4cf', '#f7e0a4', '#dcb46a', '#c08d40',
    ]);
    drawText(ctx, 'THE ARENA IS SILENT', 240, 90, { scale: 1, color: '#b9a99a', spacing: 3, align: 'center' });
    drawText(ctx, `SCORE ${Math.floor(this.score)}   \u00b7   KILLS ${this.kills}   \u00b7   BEST COMBO x${this.bestCombo}`, 240, 106, {
      scale: 1, color: '#8a7a68', spacing: 1, align: 'center',
    });
    const labels = ['PLAY AGAIN', 'MAIN MENU'];
    for (let i = 0; i < 2; i++) {
      const r = this.overlayButtonRect(i, 2);
      const sel = i === this.overlayIndex;
