  const willPause = !this.paused;
  this.paused = willPause;
  this.pauseIndex = 0;
  audio.sfx(willPause ? 'back' : 'select');
  if (willPause) audio.setMode('menu');
  else audio.setMode('battle');
  // Escape maps to both "pause" and "back"; consume both so the pause
