  }

  // pause tap target on touch
  if (this.app.isTouch && this.status === 'playing' && !this.paused) {
    px(ctx, 458, 8, 14, 14, 'rgba(10,4,4,0.7)');
    px(ctx, 462, 11, 2, 8, '#b9a99a');
    px(ctx, 466, 11, 2, 8, '#b9a99a');
  }
}

